export const VOCABULARY=[{"word":"good","pos":"adjective","chinese":"好的；好","level":"A1","sentences":[{"en":"This coffee is really good — what blend is it?","zh":"這咖啡真的很好喝——是什麼配方？"},{"en":"You did a good job on that presentation.","zh":"你的報告做得很好。"},{"en":"Is the weather good there right now?","zh":"那裡的天氣現在好嗎？"},{"en":"She has a good heart — always thinking of others.","zh":"她心地很好——總是想到別人。"},{"en":"That is a good idea. Let's try it.","zh":"那是個好主意，我們試試看。"},{"en":"I do not feel so good today — might be coming down with something.","zh":"我今天感覺不太好——可能要生病了。"},{"en":"He speaks good English for someone who just started.","zh":"對於剛開始學的人來說，他的英文說得很好。"},{"en":"That film was really good — I did not expect it.","zh":"那部電影真的很好看——我沒想到。"},{"en":"Good morning! How did you sleep?","zh":"早安！你睡得怎麼樣？"},{"en":"It feels good to finish what you started.","zh":"完成你開始的事情感覺很好。"}]},{"word":"nice","pos":"adjective","chinese":"好的；友善的","level":"A1","sentences":[{"en":"That is such a nice thing to say — thank you.","zh":"說這話真的很好——謝謝你。"},{"en":"It was nice seeing you again after so long.","zh":"這麼久之後再見到你真的很好。"},{"en":"She is really nice — everyone gets along with her.","zh":"她真的很友善——每個人都和她相處得很好。"},{"en":"This is a nice area — very quiet and clean.","zh":"這是個不錯的地方——很安靜很乾淨。"},{"en":"Have a nice weekend! See you Monday.","zh":"祝你週末愉快！週一見。"},{"en":"The weather is so nice today — let's sit outside.","zh":"今天天氣真好——我們坐外面吧。"},{"en":"It would be nice to travel again someday.","zh":"希望有一天能再去旅行。"},{"en":"That is a nice colour on you.","zh":"那個顏色很適合你。"},{"en":"He has a nice way of explaining complicated things.","zh":"他有一種很好的方式來解釋複雜的事情。"},{"en":"It is nice to have someone to talk to.","zh":"有人可以傾訴真的很好。"}]},{"word":"great","pos":"adjective","chinese":"很棒的","level":"A1","sentences":[{"en":"That sounds like a great idea — count me in.","zh":"那聽起來是個好主意——算我一個。"},{"en":"She did a great job under a lot of pressure.","zh":"她在很大壓力下表現得很棒。"},{"en":"We had a great time at the festival last weekend.","zh":"我們上週末在節慶上玩得很開心。"},{"en":"I feel great today — slept well and ate well.","zh":"我今天感覺很棒——睡得好，吃得好。"},{"en":"That is great news! I am so happy for you.","zh":"那是個好消息！我真的為你高興。"},{"en":"He is a great listener — never interrupts.","zh":"他是個很好的傾聽者——從不打斷。"},{"en":"The view from up here is great.","zh":"從這上面看的風景很棒。"},{"en":"It is great to finally meet you in person.","zh":"終於見到你本人真的很好。"},{"en":"She always has great recommendations for food.","zh":"她在食物方面總是有很棒的推薦。"},{"en":"Being in a great mood today — no reason really.","zh":"今天心情很好——沒有特別的原因。"}]},{"word":"bad","pos":"adjective","chinese":"壞的；不好的","level":"A1","sentences":[{"en":"I had a really bad day — everything went wrong.","zh":"我今天真的很倒霉——什麼都出了問題。"},{"en":"That is bad news — I am sorry to hear that.","zh":"那是個壞消息——很遺憾聽到這個。"},{"en":"She is not bad at cooking — just needs more practice.","zh":"她的廚藝不差——只是需要更多練習。"},{"en":"I feel bad about missing your birthday.","zh":"我對錯過你的生日感到很抱歉。"},{"en":"That decision turned out to be a bad one.","zh":"那個決定結果是個壞決定。"},{"en":"The traffic was so bad I was an hour late.","zh":"交通太糟了，我遲到了一個小時。"},{"en":"He had a bad week — give him some space.","zh":"他這週很糟糕——給他一些空間。"},{"en":"Bad weather always puts me in a bad mood.","zh":"壞天氣總是讓我心情不好。"},{"en":"It is not as bad as it seems from the outside.","zh":"它不像從外面看起來那麼糟。"},{"en":"She turned a bad situation into something positive.","zh":"她把一個糟糕的情況轉變成了積極的事情。"}]},{"word":"hot","pos":"adjective","chinese":"熱的；辣的","level":"A1","sentences":[{"en":"It is so hot today — I cannot go outside.","zh":"今天真的很熱——我沒辦法出去。"},{"en":"Be careful — the plate is still hot.","zh":"小心——盤子還是熱的。"},{"en":"She drinks hot water every morning before coffee.","zh":"她每天早上喝熱水，再喝咖啡。"},{"en":"Is that too hot? I can wait for it to cool down.","zh":"那個太燙嗎？我可以等它冷卻。"},{"en":"The soup is piping hot — give it a minute.","zh":"湯非常燙——等一下再喝。"},{"en":"I love hot showers — especially in winter.","zh":"我喜歡熱水澡——尤其是在冬天。"},{"en":"That chilli was so hot my eyes watered.","zh":"那個辣椒太辣了，我的眼睛都流淚了。"},{"en":"Can I get a hot chocolate, please?","zh":"我可以要一杯熱巧克力嗎？"},{"en":"The room gets hot in summer without air conditioning.","zh":"夏天沒有空調，房間會變得很熱。"},{"en":"Hot tea on a cold day is the best.","zh":"寒冷的日子裡喝熱茶是最好的。"}]},{"word":"cold","pos":"adjective","chinese":"冷的；寒冷的","level":"A1","sentences":[{"en":"I am so cold — where is my jacket?","zh":"我好冷——我的夾克在哪裡？"},{"en":"The water is cold — too cold to swim.","zh":"水很冷——太冷了，不能游泳。"},{"en":"She caught a cold from working in the rain.","zh":"她因在雨中工作而感冒了。"},{"en":"Can I have a cold drink? I am thirsty.","zh":"我可以要一杯冷飲嗎？我渴了。"},{"en":"It gets very cold here in January.","zh":"這裡一月份會變得很冷。"},{"en":"I left the window open and now it is freezing cold inside.","zh":"我把窗戶開著，現在室內冰冷。"},{"en":"The leftovers are cold — should I heat them up?","zh":"剩菜是冷的——我應該加熱嗎？"},{"en":"She does not mind the cold — she loves winter.","zh":"她不介意寒冷——她喜歡冬天。"},{"en":"My hands are so cold I can barely type.","zh":"我的手太冷了，幾乎無法打字。"},{"en":"Cold weather makes me want to stay home.","zh":"寒冷的天氣讓我想待在家裡。"}]},{"word":"want","pos":"verb","chinese":"想要","level":"A1","sentences":[{"en":"I want to travel more this year.","zh":"我今年想要多旅行。"},{"en":"What do you want for dinner tonight?","zh":"你今晚想吃什麼？"},{"en":"She wants to change jobs but is not sure where to start.","zh":"她想換工作，但不確定從哪裡開始。"},{"en":"I want to tell you something but I am not sure how.","zh":"我想告訴你一些事情，但我不確定怎麼說。"},{"en":"Do you want another cup of coffee?","zh":"你想再來一杯咖啡嗎？"},{"en":"He wants to learn how to cook.","zh":"他想學如何烹飪。"},{"en":"I do not want to be late — let's leave now.","zh":"我不想遲到——我們現在走吧。"},{"en":"All I want is a quiet evening at home.","zh":"我想要的只是一個安靜的居家夜晚。"},{"en":"She wants more time for herself.","zh":"她想要更多屬於自己的時間。"},{"en":"Just say what you want — I will not judge.","zh":"就說你想要什麼——我不會評判你。"}]},{"word":"need","pos":"verb","chinese":"需要","level":"A1","sentences":[{"en":"I need to call my parents — it has been a while.","zh":"我需要打電話給我的父母——已經有一段時間了。"},{"en":"Do you need help with that?","zh":"你需要幫忙嗎？"},{"en":"She needs more time to think about her decision.","zh":"她需要更多時間來思考她的決定。"},{"en":"I need a break — I have been working all day.","zh":"我需要休息——我工作了一整天。"},{"en":"We need to talk. Can you call me later?","zh":"我們需要談談，你稍後可以打電話給我嗎？"},{"en":"He needs reminding or he forgets everything.","zh":"他需要有人提醒，否則他會忘記一切。"},{"en":"I do not need advice — I just need someone to listen.","zh":"我不需要建議——我只是需要有人傾聽。"},{"en":"What do you need from the supermarket?","zh":"你需要從超市買什麼？"},{"en":"She needs a change of scenery — same place every day is hard.","zh":"她需要換個環境——每天待在同一個地方很難。"},{"en":"I need coffee to function in the morning.","zh":"我早上需要咖啡才能運作。"}]},{"word":"love","pos":"verb/noun","chinese":"愛；喜愛","level":"A1","sentences":[{"en":"I love the smell of coffee in the morning.","zh":"我喜歡早晨咖啡的香味。"},{"en":"She loves her job — you can see it in everything she does.","zh":"她熱愛她的工作——從她做的每一件事都能看出來。"},{"en":"I love spending lazy weekends at home.","zh":"我喜歡在家度過慵懶的週末。"},{"en":"He told her he loved her for the first time.","zh":"他第一次告訴她他愛她。"},{"en":"I love this song — turn it up!","zh":"我喜歡這首歌——把音量調大！"},{"en":"She fell in love with the city from the first day.","zh":"她從第一天就愛上了這座城市。"},{"en":"I love how honest you are with me.","zh":"我喜歡你對我如此誠實。"},{"en":"We love going to that café on Sunday mornings.","zh":"我們喜歡在週日早上去那家咖啡廳。"},{"en":"I love you — not just as a saying, but for real.","zh":"我愛你——不只是說說，是真的。"},{"en":"She loves cooking for people — it is how she shows care.","zh":"她喜歡為別人做飯——那是她表達關懷的方式。"}]},{"word":"like","pos":"verb","chinese":"喜歡","level":"A1","sentences":[{"en":"I like this place — can we come back here?","zh":"我喜歡這個地方——我們可以再來嗎？"},{"en":"Do you like spicy food or do you prefer mild?","zh":"你喜歡辣的食物還是淡的？"},{"en":"She likes working alone — gets more done that way.","zh":"她喜歡獨自工作——那樣效率更高。"},{"en":"I like how you explained that — very clear.","zh":"我喜歡你解釋那個的方式——非常清楚。"},{"en":"He likes simple things — a good book and a quiet evening.","zh":"他喜歡簡單的事情——一本好書和一個安靜的夜晚。"},{"en":"I did not like the movie — not my type.","zh":"我不喜歡那部電影——不是我的類型。"},{"en":"What kind of music do you like?","zh":"你喜歡什麼類型的音樂？"},{"en":"I like the idea but I am not sure about the timing.","zh":"我喜歡這個想法，但我不確定時機是否合適。"},{"en":"She likes being around people who make her laugh.","zh":"她喜歡和讓她發笑的人在一起。"},{"en":"Do you like your new flat? Is it comfortable?","zh":"你喜歡你的新公寓嗎？舒適嗎？"}]},{"word":"think","pos":"verb","chinese":"認為；想","level":"A1","sentences":[{"en":"I think we should leave before it gets dark.","zh":"我認為我們應該在天黑前離開。"},{"en":"She thinks too much and ends up doing nothing.","zh":"她想太多了，結果什麼都沒做。"},{"en":"What do you think of the new design?","zh":"你覺得新設計怎麼樣？"},{"en":"I did not think it would be this hard.","zh":"我沒想到會這麼難。"},{"en":"He thinks deeply before he speaks — I admire that.","zh":"他說話之前深思熟慮——我很欽佩這一點。"},{"en":"I think she is right but I am not sure.","zh":"我認為她是對的，但我不確定。"},{"en":"Do not overthink it — just decide.","zh":"不要想太多——就做決定吧。"},{"en":"I think we need to change the plan.","zh":"我認為我們需要改變計畫。"},{"en":"She thinks of everyone else before herself.","zh":"她總是先考慮別人，再考慮自己。"},{"en":"Just let me think for a moment.","zh":"讓我想一下。"}]},{"word":"feel","pos":"verb","chinese":"感覺；感受","level":"A1","sentences":[{"en":"I feel a lot better after talking to you.","zh":"和你聊過之後我感覺好多了。"},{"en":"She feels anxious before big presentations.","zh":"她在大型報告前感到焦慮。"},{"en":"How do you feel about the changes?","zh":"你對這些改變有什麼感受？"},{"en":"I feel like something is off today but I cannot explain it.","zh":"我今天感覺有什麼不對勁，但說不清楚。"},{"en":"He feels most alive when he is creating.","zh":"他在創作時感到最有活力。"},{"en":"I feel proud of how far I have come.","zh":"我為自己走了多遠感到驕傲。"},{"en":"She feels more like herself after some alone time.","zh":"獨處一段時間後，她感覺更像自己了。"},{"en":"Do not ignore how you feel — it matters.","zh":"不要忽視你的感受——那很重要。"},{"en":"I feel grateful for small things lately.","zh":"最近我對小事感到感激。"},{"en":"Feeling understood is one of the best feelings.","zh":"感到被理解是最好的感受之一。"}]},{"word":"know","pos":"verb","chinese":"知道；了解","level":"A1","sentences":[{"en":"I do not know the answer — let me look it up.","zh":"我不知道答案——讓我查一下。"},{"en":"She knows everyone in the neighbourhood.","zh":"她認識附近所有的人。"},{"en":"I know I should go to bed earlier — I just cannot.","zh":"我知道我應該早點睡——但我就是做不到。"},{"en":"Do you know a good dentist in this area?","zh":"你知道這一帶有好的牙醫嗎？"},{"en":"He knows a lot about history — ask him anything.","zh":"他對歷史了解很多——問他什麼都可以。"},{"en":"I know how you feel — I went through the same thing.","zh":"我了解你的感受——我也經歷過同樣的事情。"},{"en":"She does not know what she wants and that is okay.","zh":"她不知道自己想要什麼，這沒關係。"},{"en":"I know it sounds crazy but it actually worked.","zh":"我知道聽起來很瘋狂，但它真的奏效了。"},{"en":"You never know until you try.","zh":"不試永遠不知道。"},{"en":"I knew this would happen — I had a feeling.","zh":"我就知道這會發生——我有預感。"}]},{"word":"say","pos":"verb","chinese":"說","level":"A1","sentences":[{"en":"What did she say about the meeting?","zh":"她對這個會議說了什麼？"},{"en":"He said something really kind and it stayed with me.","zh":"他說了一些非常友善的話，一直留在我心裡。"},{"en":"I did not know what to say so I said nothing.","zh":"我不知道說什麼，所以什麼都沒說。"},{"en":"She always says exactly what she thinks.","zh":"她總是直接說出她的想法。"},{"en":"Say it again — I could not hear you.","zh":"再說一遍——我聽不到你說什麼。"},{"en":"They say the best things in life are free.","zh":"人們說生命中最美好的事情是免費的。"},{"en":"I said I was sorry and I meant it.","zh":"我說了對不起，我是認真的。"},{"en":"What are you trying to say? Just say it.","zh":"你想說什麼？就說出來。"},{"en":"She said yes and everything changed.","zh":"她說了好，一切都改變了。"},{"en":"I said no and felt completely fine about it.","zh":"我說了不，感覺完全沒問題。"}]},{"word":"go","pos":"verb","chinese":"去；走","level":"A1","sentences":[{"en":"Let us go before it gets crowded.","zh":"我們去吧，在變得擁擠之前。"},{"en":"Where do you want to go this weekend?","zh":"你這個週末想去哪裡？"},{"en":"She goes for a run every morning without fail.","zh":"她每天早上都固定去跑步。"},{"en":"I did not want to go but I am glad I did.","zh":"我當初不想去，但很高興我去了。"},{"en":"How did the interview go?","zh":"面試進行得怎樣？"},{"en":"Go on — tell me what happened.","zh":"繼續——告訴我發生了什麼。"},{"en":"Time goes so fast when I am busy.","zh":"我忙的時候時間過得好快。"},{"en":"She goes to the library every Sunday.","zh":"她每個週日都去圖書館。"},{"en":"Let it go — it is not worth the stress.","zh":"放手吧——不值得費心。"},{"en":"Everything is going to be okay.","zh":"一切都會沒事的。"}]},{"word":"come","pos":"verb","chinese":"來；到來","level":"A1","sentences":[{"en":"Can you come over later? I need help.","zh":"你稍後可以過來嗎？我需要幫忙。"},{"en":"She came all the way just to check on me.","zh":"她特地趕來只是為了關心我。"},{"en":"Come and sit with me for a bit.","zh":"過來陪我坐一會兒。"},{"en":"I did not come here to argue.","zh":"我來這裡不是為了爭論。"},{"en":"Success does not come overnight.","zh":"成功不是一蹴而就的。"},{"en":"He came back changed after his year abroad.","zh":"他在國外一年後回來，已經變了一個人。"},{"en":"Come on — we are going to be late.","zh":"快點——我們要遲到了。"},{"en":"When the opportunity comes, take it.","zh":"機會來臨時，就抓住它。"},{"en":"She comes to mind when I see anything beautiful.","zh":"每當我看到美麗的事物，就會想起她。"},{"en":"Spring always comes — even after the hardest winter.","zh":"春天總會來臨——即使在最嚴酷的冬天之後。"}]},{"word":"take","pos":"verb","chinese":"拿；帶；需要","level":"A1","sentences":[{"en":"Can you take a photo of us?","zh":"你能幫我們拍張照嗎？"},{"en":"It takes time to build real trust.","zh":"建立真正的信任需要時間。"},{"en":"She took a deep breath before speaking.","zh":"她在說話前深吸一口氣。"},{"en":"Take your time — there is no rush.","zh":"慢慢來——不用急。"},{"en":"I take the bus every morning to work.","zh":"我每天早上坐公車上班。"},{"en":"He took a chance and it paid off.","zh":"他冒了一個險，結果得到了回報。"},{"en":"Can I take a look at that?","zh":"我可以看看那個嗎？"},{"en":"She takes great care of the people around her.","zh":"她非常照顧身邊的人。"},{"en":"It took me a year to feel settled here.","zh":"我花了一年時間才在這裡安定下來。"},{"en":"Take it easy — you have done enough for today.","zh":"放鬆一下——你今天已經做得夠多了。"}]},{"word":"make","pos":"verb","chinese":"做；製作；使","level":"A1","sentences":[{"en":"I will make dinner tonight — you rest.","zh":"我今晚做晚飯——你休息。"},{"en":"She makes everything look easy.","zh":"她讓一切看起來都很容易。"},{"en":"What makes you happy on a regular day?","zh":"在平常的日子裡，什麼讓你快樂？"},{"en":"I made a mistake and I own it.","zh":"我犯了一個錯誤，我承擔責任。"},{"en":"Can you make time to meet this week?","zh":"你這週有時間見面嗎？"},{"en":"He makes people feel welcome wherever he goes.","zh":"他走到哪裡都讓人感到受歡迎。"},{"en":"I am trying to make better decisions.","zh":"我在努力做出更好的決定。"},{"en":"She made a big change and never looked back.","zh":"她做了一個大改變，從此再也沒有回頭看。"},{"en":"Make the most of every moment.","zh":"充分利用每一個時刻。"},{"en":"That made my whole day — thank you.","zh":"那讓我整天都很開心——謝謝你。"}]},{"word":"give","pos":"verb","chinese":"給","level":"A1","sentences":[{"en":"She gave me the best advice I have ever received.","zh":"她給了我我曾收到過的最好的建議。"},{"en":"I want to give back to my community.","zh":"我想回饋我的社區。"},{"en":"Can you give me a hand with this?","zh":"你能幫我一下嗎？"},{"en":"He gives everything he has to the people he loves.","zh":"他把他所有的一切都給了他愛的人。"},{"en":"I gave up on that habit and do not regret it.","zh":"我放棄了那個習慣，不後悔。"},{"en":"Give it time — things will improve.","zh":"給它時間——事情會改善的。"},{"en":"She gave me a hug and I needed it.","zh":"她給了我一個擁抱，我很需要那個。"},{"en":"I will give it another try — one more chance.","zh":"我會再試一次——再給一次機會。"},{"en":"He gives the best gifts — always thoughtful.","zh":"他送的禮物最好——總是很用心。"},{"en":"Give yourself credit for how far you have come.","zh":"為你走過的路給自己一些認可。"}]},{"word":"get","pos":"verb","chinese":"得到；變得","level":"A1","sentences":[{"en":"I got a call from an old friend today.","zh":"我今天接到了一個老朋友的電話。"},{"en":"She gets nervous before every performance.","zh":"她每次表演前都會緊張。"},{"en":"Can you get me a coffee while you are up?","zh":"你站起來的時候可以幫我拿一杯咖啡嗎？"},{"en":"I am getting better at saying no.","zh":"我越來越擅長說不了。"},{"en":"He gets along with everyone — very likeable.","zh":"他和所有人都相處得很好——非常討人喜歡。"},{"en":"We are getting closer to our goal.","zh":"我們正在接近我們的目標。"},{"en":"I got what I needed from that conversation.","zh":"我從那次對話中得到了我需要的東西。"},{"en":"She gets up at five every morning — impressive.","zh":"她每天早上五點起床——令人印象深刻。"},{"en":"Get some rest — you look exhausted.","zh":"好好休息——你看起來很疲憊。"},{"en":"I cannot get this song out of my head.","zh":"我腦海中一直循環著這首歌。"}]},{"word":"see","pos":"verb","chinese":"看見;見到","level":"A1","sentences":[{"en":"I see what you mean now — that makes sense.","zh":"我現在明白你的意思了——這說得通。"},{"en":"Can you see the mountains from your window?","zh":"你從窗戶能看到山嗎？"},{"en":"She saw him across the room and smiled.","zh":"她在房間另一頭看到他，笑了。"},{"en":"Let me see — where did I put my keys?","zh":"讓我想想——我把鑰匙放在哪裡了？"},{"en":"I see her every Tuesday at the café.","zh":"我每個星期二在咖啡廳見到她。"},{"en":"Do you see that building? That is where I work.","zh":"你看到那棟大樓嗎？那是我工作的地方。"},{"en":"I saw the most beautiful sunset yesterday.","zh":"我昨天看到了最美麗的日落。"},{"en":"He could not see the screen from where he was sitting.","zh":"他從他坐的地方看不到螢幕。"},{"en":"See you tomorrow!","zh":"明天見！"},{"en":"I see your point — let me think about it.","zh":"我明白你的觀點——讓我想一想。"}]},{"word":"look","pos":"verb","chinese":"看；看起來","level":"A1","sentences":[{"en":"You look really tired — are you okay?","zh":"你看起來真的很累——你還好嗎？"},{"en":"Look at this photo — is that not beautiful?","zh":"看看這張照片——是不是很漂亮？"},{"en":"She looks exactly like her mother.","zh":"她看起來和她媽媽一模一樣。"},{"en":"Can you look this up for me? I do not know the word.","zh":"你能幫我查一下嗎？我不認識這個詞。"},{"en":"He looked at her and smiled without saying anything.","zh":"他看著她，什麼都沒說，微笑了。"},{"en":"Look out! There is a step there.","zh":"小心！那裡有一個臺階。"},{"en":"This looks delicious — what is it?","zh":"這看起來很好吃——這是什麼？"},{"en":"I looked everywhere but could not find it.","zh":"我到處找，但找不到。"},{"en":"Do not look at me like that — I did nothing wrong.","zh":"不要那樣看著我——我沒有做錯任何事。"},{"en":"You should look at this — it is really interesting.","zh":"你應該看看這個——真的很有趣。"}]},{"word":"hear","pos":"verb","chinese":"聽到;聽說","level":"A1","sentences":[{"en":"Did you hear that? It sounded like someone knocked.","zh":"你聽到了嗎？聽起來像是有人在敲。"},{"en":"I heard she got promoted — good for her.","zh":"我聽說她升職了——替她高興。"},{"en":"Can you speak up? I cannot hear you well.","zh":"你能大聲點嗎？我聽不清楚你說話。"},{"en":"She heard the news and immediately called me.","zh":"她聽到消息後立刻打電話給我。"},{"en":"I have heard that restaurant is amazing.","zh":"我聽說那家餐廳很棒。"},{"en":"He heard her singing and stopped to listen.","zh":"他聽到她在唱歌，停下來聆聽。"},{"en":"I do not want to hear any excuses.","zh":"我不想聽任何藉口。"},{"en":"Have you heard from her recently?","zh":"你最近有她的消息嗎？"},{"en":"I hear you — that sounds really frustrating.","zh":"我明白你——那聽起來真的很令人沮喪。"},{"en":"She did not hear her alarm and woke up late.","zh":"她沒有聽到鬧鐘，起床晚了。"}]},{"word":"help","pos":"verb/noun","chinese":"幫助；幫忙","level":"A1","sentences":[{"en":"Can you help me with this? I am stuck.","zh":"你能幫我解決這個嗎？我卡住了。"},{"en":"She helped me move last weekend — such a good friend.","zh":"她上週末幫我搬家——真是個好朋友。"},{"en":"Is there anything I can help with?","zh":"有什麼我可以幫忙的嗎？"},{"en":"That advice really helped — thank you.","zh":"那個建議真的很有幫助——謝謝你。"},{"en":"He helps his grandmother with her shopping every week.","zh":"他每週幫祖母購物。"},{"en":"I cannot help how I feel about it.","zh":"我無法控制我對此的感受。"},{"en":"Please help yourself to food and drinks.","zh":"請自便，享用食物和飲料。"},{"en":"She needs help — do not pretend you do not see it.","zh":"她需要幫助——不要假裝你看不見。"},{"en":"A good friend does not wait to be asked for help.","zh":"好朋友不會等到被要求才幫忙。"},{"en":"How can I help you today?","zh":"我今天怎樣幫到你？"}]},{"word":"ask","pos":"verb","chinese":"問；請求","level":"A1","sentences":[{"en":"Can I ask you something personal?","zh":"我能問你一個私人問題嗎？"},{"en":"She asked for help and was not ashamed of it.","zh":"她請求幫助，並不為此感到羞恥。"},{"en":"He asked the question everyone was thinking.","zh":"他問了每個人都在想的問題。"},{"en":"Do not be afraid to ask when you do not understand.","zh":"不懂的時候不要害怕開口問。"},{"en":"I asked her if she was okay and she just shrugged.","zh":"我問她是否還好，她只是聳聳肩。"},{"en":"She asked to leave early — the boss said yes.","zh":"她請求提早離開——老闆答應了。"},{"en":"Ask and you might just get what you need.","zh":"開口問，你可能會得到你需要的。"},{"en":"I am just asking — no pressure at all.","zh":"我只是問問——完全沒有壓力。"},{"en":"He asked for a second opinion before deciding.","zh":"他在決定之前請求了第二意見。"},{"en":"If you do not ask, the answer is always no.","zh":"如果你不開口問，答案永遠是不。"}]},{"word":"tell","pos":"verb","chinese":"告訴；說明","level":"A1","sentences":[{"en":"Tell me what happened — from the beginning.","zh":"告訴我發生了什麼——從頭說起。"},{"en":"She told him the truth and it changed everything.","zh":"她告訴了他真相，這改變了一切。"},{"en":"I cannot tell if he is serious or joking.","zh":"我分不清楚他是認真的還是在開玩笑。"},{"en":"Can you tell me how to get there from here?","zh":"你能告訴我怎樣從這裡到那裡嗎？"},{"en":"He told me something I will never forget.","zh":"他告訴了我一些我永遠不會忘記的事情。"},{"en":"Tell me about yourself — what do you enjoy?","zh":"告訴我關於你的事情——你喜歡什麼？"},{"en":"I told you so — I knew this would happen.","zh":"我就說吧——我知道這會發生。"},{"en":"She told a story that made everyone laugh.","zh":"她講了一個讓所有人都笑了的故事。"},{"en":"You can tell a lot about a person by how they treat waiters.","zh":"你可以從一個人對待服務員的方式看出很多事情。"},{"en":"He told her he would be late but she forgot.","zh":"他告訴她他會遲到，但她忘了。"}]},{"word":"try","pos":"verb","chinese":"嘗試；試試","level":"A1","sentences":[{"en":"You will not know until you try.","zh":"你嘗試之前不會知道。"},{"en":"She tried a new recipe and it turned out perfectly.","zh":"她嘗試了一個新食譜，結果做得非常完美。"},{"en":"I tried to explain but he was not listening.","zh":"我試著解釋，但他沒有在聽。"},{"en":"Try not to worry too much — it will work out.","zh":"試著不要太擔心——事情會好起來的。"},{"en":"He tried three times before getting it right.","zh":"他嘗試了三次才做對。"},{"en":"Have you tried talking to her about it?","zh":"你有沒有嘗試和她談談這件事？"},{"en":"I always try to be on time — I hate being late.","zh":"我總是努力準時——我討厭遲到。"},{"en":"She tried something new and discovered a passion.","zh":"她嘗試了新事物，發現了一個熱情。"},{"en":"At least I tried — no regrets.","zh":"至少我嘗試了——沒有遺憾。"},{"en":"Try again. You were so close.","zh":"再試一次，你非常接近了。"}]},{"word":"talk","pos":"verb","chinese":"說話；聊天","level":"A1","sentences":[{"en":"We need to talk — do you have a few minutes?","zh":"我們需要聊聊——你有幾分鐘嗎？"},{"en":"She talks to her plants. I respect that.","zh":"她和她的植物說話，我很欣賞。"},{"en":"Can we talk about this later — I am in a meeting.","zh":"我們可以晚點聊嗎——我在開會。"},{"en":"He is the kind of person who talks to everyone.","zh":"他是那種和所有人說話的人。"},{"en":"I love talking to you — time flies.","zh":"我喜歡和你聊天——時間飛逝。"},{"en":"She talked about her trip for an hour and I loved every minute.","zh":"她談了一個小時的旅行，我每一分鐘都很享受。"},{"en":"Do not talk to me before my coffee.","zh":"在我喝咖啡之前不要和我說話。"},{"en":"Talking through a problem helps more than just thinking about it.","zh":"把問題說出來比只是想更有幫助。"},{"en":"We talked until three in the morning and did not notice the time.","zh":"我們聊到凌晨三點，沒有注意到時間。"},{"en":"He talks less but says more — I admire that.","zh":"他說的少，但說的更有意義——我很欣賞這一點。"}]},{"word":"move","pos":"verb","chinese":"移動；搬家","level":"A1","sentences":[{"en":"Can you move a little to the left? You are blocking the view.","zh":"你能往左移一點嗎？你擋住了視線。"},{"en":"She moved to a new city and started fresh.","zh":"她搬到了一個新城市，重新開始。"},{"en":"That speech moved me — I actually cried.","zh":"那篇演講讓我很感動——我真的哭了。"},{"en":"He moves so fast — I can barely keep up.","zh":"他動作那麼快——我幾乎跟不上。"},{"en":"I need to move this meeting — can we push it back?","zh":"我需要調整這個會議——我們能推遲嗎？"},{"en":"They moved in together after two years.","zh":"他們在兩年後搬到了一起。"},{"en":"Move on — dwelling on it will not help.","zh":"繼續前進——糾結於此沒有幫助。"},{"en":"She was moved by the kindness of a stranger.","zh":"她被一個陌生人的善意感動了。"},{"en":"He moved slowly but with complete intention.","zh":"他動作緩慢，但非常有目的性。"},{"en":"Moving is stressful but starting somewhere new is exciting.","zh":"搬家很有壓力，但在新的地方開始是令人興奮的。"}]},{"word":"open","pos":"verb/adjective","chinese":"打開；開放的","level":"A1","sentences":[{"en":"Can you open the window? It is stuffy in here.","zh":"你能打開窗戶嗎？這裡悶。"},{"en":"The café opens at seven — are you an early riser?","zh":"咖啡廳七點開門——你是早起的人嗎？"},{"en":"She is very open about her feelings — I respect that.","zh":"她對她的感受非常開放——我很尊重這一點。"},{"en":"He opened the email and stared at the screen for a while.","zh":"他打開了電子郵件，盯著螢幕看了一會兒。"},{"en":"Keep an open mind — you might like it.","zh":"保持開放的心態——你可能會喜歡它。"},{"en":"She opened up to me and I felt honoured.","zh":"她向我打開心扉，我感到很榮幸。"},{"en":"Are you open this weekend or fully booked?","zh":"你這個週末有空還是完全排滿了？"},{"en":"He opened the door for her — small gesture, big impact.","zh":"他為她開門——小動作，大影響。"},{"en":"I like restaurants with an open kitchen — you see everything.","zh":"我喜歡有開放式廚房的餐廳——你可以看到一切。"},{"en":"Opening up is scary but it creates real connection.","zh":"敞開心扉是可怕的，但它建立了真實的連結。"}]},{"word":"close","pos":"verb/adjective","chinese":"關閉；關上；親密的","level":"A1","sentences":[{"en":"Can you close the door behind you?","zh":"你能幫我帶上門嗎？"},{"en":"The shop closes at nine on weekdays.","zh":"這家店工作日九點關門。"},{"en":"They are very close — more like siblings than friends.","zh":"他們非常親密——與其說是朋友，不如說是兄弟姐妹。"},{"en":"Close your eyes and take a deep breath.","zh":"閉上眼睛，深深地吸一口氣。"},{"en":"The deadline is close — we need to hurry.","zh":"截止日期快到了——我們需要加快速度。"},{"en":"She was close to finishing when the power cut out.","zh":"她快要完成了，這時停電了。"},{"en":"He sat close and spoke softly.","zh":"他坐得很近，輕聲說話。"},{"en":"Closing a chapter is hard but necessary to start a new one.","zh":"結束一個章節很難，但對於開始新章節是必要的。"},{"en":"They have been close friends since childhood.","zh":"他們從童年起就是親密的朋友。"},{"en":"That was close! You almost missed the train.","zh":"好險！你差點錯過了火車。"}]},{"word":"wait","pos":"verb","chinese":"等待；等","level":"A1","sentences":[{"en":"I have been waiting for thirty minutes — where are you?","zh":"我已經等了三十分鐘了——你在哪裡？"},{"en":"Good things are worth waiting for.","zh":"好的事情值得等待。"},{"en":"She waited patiently without complaining once.","zh":"她耐心地等著，一次也沒抱怨。"},{"en":"Wait — let me explain before you make a decision.","zh":"等等——在你做決定之前讓我解釋。"},{"en":"I cannot wait to see you again.","zh":"我迫不及待地想再見到你。"},{"en":"He waited in line for two hours for that new café.","zh":"他為了那家新咖啡廳排了兩個小時的隊。"},{"en":"Do not wait for the perfect moment — make the moment.","zh":"不要等待完美的時機——創造時機。"},{"en":"I am waiting on a reply — I will know tomorrow.","zh":"我在等回覆——明天就會知道了。"},{"en":"She told me to wait outside but that was an hour ago.","zh":"她叫我在外面等，但那是一個小時前的事了。"},{"en":"Waiting is a skill — some people never master it.","zh":"等待是一種技能——有些人永遠無法掌握它。"}]},{"word":"leave","pos":"verb","chinese":"離開；留下","level":"A1","sentences":[{"en":"I have to leave now — early morning tomorrow.","zh":"我現在要走了——明天一早有事。"},{"en":"She left her job and never looked back.","zh":"她辭掉了工作，再也沒有回頭看。"},{"en":"Do not leave without saying goodbye.","zh":"不要不說再見就離開。"},{"en":"He left his phone at the restaurant — had to go back.","zh":"他把手機落在了餐廳——不得不回去拿。"},{"en":"Leave it — it is not worth your energy.","zh":"算了——不值得你花精力。"},{"en":"She always leaves things better than she found them.","zh":"她總是讓事情比她發現時更好。"},{"en":"I left the light on — again.","zh":"我又忘記關燈了。"},{"en":"Can we leave by six to beat the traffic?","zh":"我們能六點前走嗎？這樣可以避開交通堵塞。"},{"en":"He left early and missed the best part.","zh":"他提前離開，錯過了最精彩的部分。"},{"en":"Leaving is hard but sometimes it is the right thing.","zh":"離開是困難的，但有時候那是正確的事情。"}]},{"word":"start","pos":"verb","chinese":"開始；出發","level":"A1","sentences":[{"en":"Let us start — we are already behind schedule.","zh":"我們開始吧——我們已經落後於計劃了。"},{"en":"She started a new chapter and was terrified and excited.","zh":"她開始了新的篇章，既害怕又興奮。"},{"en":"Where should I start? There is so much to say.","zh":"我應該從哪裡開始？有太多要說了。"},{"en":"He started small and built something incredible.","zh":"他從小做起，建立了令人難以置信的事業。"},{"en":"Start with one thing — do not overwhelm yourself.","zh":"從一件事開始——不要讓自己不知所措。"},{"en":"She started the meeting by thanking everyone for their time.","zh":"她通過感謝大家抽出時間來開始了會議。"},{"en":"I started cooking and forgot about time completely.","zh":"我開始做飯，完全忘記了時間。"},{"en":"He started over with nothing and rebuilt everything.","zh":"他從零開始，重建了一切。"},{"en":"Start each day fresh — yesterday does not define today.","zh":"以全新的狀態開始每一天——昨天不定義今天。"},{"en":"She started her business in her bedroom — now it is international.","zh":"她在臥室裡創業——現在是國際公司了。"}]},{"word":"stop","pos":"verb","chinese":"停止；停下","level":"A1","sentences":[{"en":"Stop — you are going to hurt yourself.","zh":"停下——你會傷到自己的。"},{"en":"She could not stop laughing — it was contagious.","zh":"她停不下來笑——那是有感染力的。"},{"en":"I keep telling myself to stop overthinking.","zh":"我一直告訴自己停止過度思考。"},{"en":"Can we stop here for a while? I like this spot.","zh":"我們能在這裡停一下嗎？我喜歡這個地方。"},{"en":"He stopped the car and looked around.","zh":"他停下車，環顧四周。"},{"en":"Stop comparing yourself to others — it is not fair to you.","zh":"停止拿自己和別人比較——對你不公平。"},{"en":"She stopped complaining and started doing.","zh":"她停止了抱怨，開始行動了。"},{"en":"I cannot stop thinking about what you said.","zh":"我停不下來想你說的話。"},{"en":"Stop. Breathe. You are doing fine.","zh":"停下來，呼吸，你做得很好。"},{"en":"When do you stop working and start living?","zh":"你什麼時候停止工作，開始生活？"}]},{"word":"bring","pos":"verb","chinese":"帶來；帶","level":"A1","sentences":[{"en":"Can you bring an umbrella? It looks like rain.","zh":"你能帶把雨傘嗎？看起來要下雨了。"},{"en":"She brought homemade cookies to the office.","zh":"她帶了自制餅乾到辦公室。"},{"en":"What can I bring to the dinner party?","zh":"我可以帶什麼去晚宴？"},{"en":"He brings a positive energy wherever he goes.","zh":"他走到哪裡都帶來積極的能量。"},{"en":"That song brings back so many memories.","zh":"那首歌勾起了太多回憶。"},{"en":"She always brings out the best in people.","zh":"她總是能激發出別人最好的一面。"},{"en":"Bring your ID or they will not let you in.","zh":"帶上你的身份證，否則他們不會讓你進去。"},{"en":"I brought coffee — thought you might need it.","zh":"我帶了咖啡——我想你可能需要。"},{"en":"He brought comfort just by being there.","zh":"他只是在那裡就帶來了安慰。"},{"en":"What brings you here today?","zh":"今天什麼風把你帶來了？"}]},{"word":"find","pos":"verb","chinese":"找到；發現","level":"A1","sentences":[{"en":"I cannot find my keys — have you seen them?","zh":"我找不到我的鑰匙——你看到了嗎？"},{"en":"She found her passion at forty — better late than never.","zh":"她在四十歲發現了她的熱情——遲到總比不到好。"},{"en":"I find this really interesting — tell me more.","zh":"我覺得這非常有趣——多說點。"},{"en":"He found the perfect café and it became his second home.","zh":"他找到了完美的咖啡廳，它成了他的第二個家。"},{"en":"I find it hard to say no sometimes.","zh":"我有時候覺得說不很難。"},{"en":"She found him exactly where he said he would be.","zh":"她在他說的地方找到了他。"},{"en":"I need to find a way to fix this.","zh":"我需要找到解決這個問題的方法。"},{"en":"He found strength he did not know he had.","zh":"他發現了他不知道自己擁有的力量。"},{"en":"Finding balance is a daily practice.","zh":"找到平衡是一種日常練習。"},{"en":"I found out the hard way — but I learned.","zh":"我用艱難的方式發現的——但我學到了東西。"}]},{"word":"eat","pos":"verb","chinese":"吃","level":"A1","sentences":[{"en":"Have you eaten? You look hungry.","zh":"你吃過了嗎？你看起來很餓。"},{"en":"She eats slowly and actually tastes her food.","zh":"她吃得很慢，真正品嚐食物。"},{"en":"We ate outside by the canal — perfect evening.","zh":"我們在運河邊的戶外吃飯——完美的夜晚。"},{"en":"I eat breakfast every day without fail.","zh":"我每天都吃早餐，毫無例外。"},{"en":"He eats everything — very easy to cook for.","zh":"他什麼都吃——非常容易為他做飯。"},{"en":"What do you want to eat tonight? I can cook.","zh":"你今晚想吃什麼？我可以做。"},{"en":"Eating together is one of my favourite things.","zh":"一起吃飯是我最喜歡的事情之一。"},{"en":"She ate her feelings after that break-up.","zh":"分手後她靠吃來疏解情緒。"},{"en":"Do not eat at your desk — take a proper break.","zh":"不要在桌子前吃飯——好好休息一下。"},{"en":"He eats so fast I worry he does not taste anything.","zh":"他吃得那麼快，我擔心他沒有嚐到任何味道。"}]},{"word":"drink","pos":"verb/noun","chinese":"喝；飲料","level":"A1","sentences":[{"en":"Can I get you a drink?","zh":"我可以給你拿一杯飲料嗎？"},{"en":"She drinks two litres of water a day — skin goals.","zh":"她每天喝兩升水——護膚目標。"},{"en":"What are you drinking? It smells delicious.","zh":"你在喝什麼？聞起來很好喝。"},{"en":"He drinks his coffee black — no sugar, no milk.","zh":"他喝黑咖啡——不加糖，不加奶。"},{"en":"I need a drink after that meeting.","zh":"那個會議之後我需要喝一杯。"},{"en":"She does not drink alcohol — and she never apologises for it.","zh":"她不喝酒——她從不為此道歉。"},{"en":"Drink more water — you probably need it.","zh":"多喝水——你可能需要。"},{"en":"We grabbed drinks after work and talked for hours.","zh":"我們下班後去喝飲料，聊了好幾個小時。"},{"en":"He ordered the most expensive drink on the menu by mistake.","zh":"他不小心點了菜單上最貴的飲料。"},{"en":"Drinking slowly and savouring the flavour is the best way.","zh":"慢慢喝，細細品味是最好的方式。"}]},{"word":"sleep","pos":"verb","chinese":"睡覺；入睡","level":"A1","sentences":[{"en":"I slept so well last night — eight full hours.","zh":"我昨晚睡得很好——整整八個小時。"},{"en":"She cannot sleep when she is anxious.","zh":"她焦慮的時候睡不著。"},{"en":"Go to sleep — it is too late to fix it tonight.","zh":"去睡覺吧——今晚解決不了了。"},{"en":"He sleeps through everything — not even thunder wakes him.","zh":"他什麼都能睡過去——連雷聲都叫不醒他。"},{"en":"I need to sleep early or tomorrow will be rough.","zh":"我需要早點睡覺，否則明天會很難熬。"},{"en":"She fell asleep in the middle of the film again.","zh":"她又在電影進行中睡著了。"},{"en":"Sleep is not laziness — it is recovery.","zh":"睡覺不是懶惰——而是恢復。"},{"en":"I slept on the problem and woke up with a solution.","zh":"我把問題留到睡一覺後，醒來有了解決方案。"},{"en":"He looks like he has not slept in days.","zh":"他看起來好幾天沒睡覺了。"},{"en":"Sleep changes everything — you are a different person after good rest.","zh":"睡眠改變一切——好好休息後你是一個不同的人。"}]},{"word":"walk","pos":"verb","chinese":"走路；散步","level":"A1","sentences":[{"en":"I walk to work — forty minutes and worth every step.","zh":"我走路上班——四十分鐘，每一步都值得。"},{"en":"She walked in like she owned the place.","zh":"她走進來，好像那是她的地盤。"},{"en":"Let us walk — it is too nice a day to take the bus.","zh":"我們走路吧——天氣太好了，不想坐公車。"},{"en":"He walks his dog every morning at six.","zh":"他每天早上六點遛他的狗。"},{"en":"Walking clears my head better than anything else.","zh":"散步比任何事情都更能清理我的思緒。"},{"en":"She walked away and never looked back.","zh":"她走開了，再也沒有回頭看。"},{"en":"We walked for hours and forgot where we were going.","zh":"我們走了好幾個小時，忘記了我們要去哪裡。"},{"en":"Walking slowly and looking around is underrated.","zh":"慢慢走，四處看看，這種方式被低估了。"},{"en":"He walked into the wrong building and had to backtrack.","zh":"他走進了錯誤的大樓，不得不退回來。"},{"en":"There is wisdom in the phrase: just walk it off.","zh":"「就走一走」這句話很有智慧。"}]},{"word":"run","pos":"verb","chinese":"跑步；運行","level":"A1","sentences":[{"en":"I run three times a week — it saves my sanity.","zh":"我每週跑三次——這讓我保持理智。"},{"en":"She ran for the bus and just made it.","zh":"她跑去趕公車，剛好趕上了。"},{"en":"He runs a small business from home.","zh":"他在家裡經營一個小生意。"},{"en":"I ran into my old classmate at the supermarket.","zh":"我在超市碰到了我的老同學。"},{"en":"Run — you are going to be late.","zh":"跑——你要遲到了。"},{"en":"She ran the meeting efficiently — in and out in thirty minutes.","zh":"她高效地主持了會議——三十分鐘內結束。"},{"en":"My phone runs out of battery by noon every day.","zh":"我的手機每天中午電量就耗盡了。"},{"en":"He ran the whole marathon without stopping.","zh":"他不停地跑完了整個馬拉松。"},{"en":"Time runs faster when I am doing something I love.","zh":"當我在做我喜歡的事情時，時間過得更快。"},{"en":"She runs on coffee and good intentions.","zh":"她靠咖啡和好意運轉。"}]},{"word":"write","pos":"verb","chinese":"寫","level":"A1","sentences":[{"en":"I write down everything I want to remember.","zh":"我把所有想記住的事情都寫下來。"},{"en":"She wrote a letter to her future self.","zh":"她給未來的自己寫了一封信。"},{"en":"Have you written the email yet?","zh":"你已經寫了那封電子郵件嗎？"},{"en":"He writes beautifully — every sentence means something.","zh":"他寫得很好——每一句話都有意義。"},{"en":"I need to write this down before I forget.","zh":"我需要在忘記之前把這個寫下來。"},{"en":"She wrote in her journal every night before bed.","zh":"她每晚睡前都在日記本上寫作。"},{"en":"Writing helps me process my feelings.","zh":"寫作幫助我處理我的情緒。"},{"en":"He wrote back immediately — I liked that.","zh":"他立刻回信了——我很喜歡。"},{"en":"Write clearly and people will take you seriously.","zh":"寫得清楚，人們就會認真對待你。"},{"en":"She wrote the proposal in one sitting — impressed everyone.","zh":"她一口氣寫完了提案——讓所有人都印象深刻。"}]},{"word":"read","pos":"verb","chinese":"讀；閱讀","level":"A1","sentences":[{"en":"I read every night before sleeping — even just one page.","zh":"我每晚睡前都會讀書——哪怕只是一頁。"},{"en":"She reads faster than anyone I know.","zh":"她讀書比我認識的任何人都快。"},{"en":"Did you read the news today? Wild stuff.","zh":"你今天看新聞了嗎？太瘋狂了。"},{"en":"I read the email three times to make sure I understood.","zh":"我把電子郵件讀了三遍，確保我理解了。"},{"en":"He reads everything — books, menus, labels.","zh":"他什麼都讀——書、菜單、標籤。"},{"en":"She read the room and knew when to stop talking.","zh":"她讀懂了場合，知道什麼時候該停止說話。"},{"en":"I love reading but struggle to find the time.","zh":"我喜歡閱讀，但很難找到時間。"},{"en":"Reading one book changed how I see the world.","zh":"讀一本書改變了我看世界的方式。"},{"en":"She reads people well — very perceptive.","zh":"她很善於讀懂人——非常敏銳。"},{"en":"I read too fast and have to go back — story of my life.","zh":"我讀得太快，不得不回去重讀——我的人生寫照。"}]},{"word":"meet","pos":"verb","chinese":"遇見；見面","level":"A1","sentences":[{"en":"Nice to meet you — I have heard great things.","zh":"很高興見到你——我聽說了很多好的事情。"},{"en":"We met at a coffee shop and talked for five hours.","zh":"我們在咖啡廳相遇，聊了五個小時。"},{"en":"Can we meet next week to discuss this?","zh":"我們下週能見面討論這個嗎？"},{"en":"She met her best friend on the first day of university.","zh":"她在大學第一天遇到了她最好的朋友。"},{"en":"I love meeting new people — you never know what you will learn.","zh":"我喜歡遇見新朋友——你永遠不知道你會學到什麼。"},{"en":"He meets every challenge with a positive attitude.","zh":"他以積極的態度應對每一個挑戰。"},{"en":"We met online before we ever met in person.","zh":"我們在線上認識，後來才見面。"},{"en":"She met my eyes and I knew she understood.","zh":"她看著我的眼睛，我知道她理解了。"},{"en":"Meeting someone who just gets you is rare.","zh":"遇見一個完全理解你的人是很難得的。"},{"en":"I cannot meet that deadline — I need more time.","zh":"我無法在那個截止日期前完成——我需要更多時間。"}]},{"word":"stay","pos":"verb","chinese":"停留；留下","level":"A1","sentences":[{"en":"Can you stay a little longer? It is early.","zh":"你能多待一會兒嗎？還早呢。"},{"en":"She stayed at a tiny guesthouse and loved every minute.","zh":"她住在一家小旅馆，每一分鐘都很享受。"},{"en":"Stay focused — the finish line is close.","zh":"保持專注——終點就在眼前。"},{"en":"He stayed calm even when everything was falling apart.","zh":"即使一切都在崩潰，他也保持冷靜。"},{"en":"I want to stay here forever.","zh":"我想永遠留在這裡。"},{"en":"She stayed true to herself even when it was hard.","zh":"即使在困難時，她也忠於自己。"},{"en":"Stay out of trouble — please.","zh":"不要惹麻煩——拜託了。"},{"en":"We stayed up talking until the sun came up.","zh":"我們聊天直到太陽升起。"},{"en":"He stays consistent — same values, same principles.","zh":"他保持一致——相同的價值觀，相同的原則。"},{"en":"Stay where you are — I am coming to you.","zh":"待在原地——我去找你。"}]},{"word":"know","pos":"verb","chinese":"知道；認識","level":"A1","sentences":[{"en":"I know you — you will figure this out.","zh":"我了解你——你會解決這個問題的。"},{"en":"She knows how to make any room feel comfortable.","zh":"她知道如何讓任何房間都感到舒適。"},{"en":"I do not know what I would do without you.","zh":"我不知道沒有你我會怎樣。"},{"en":"He knows more than he lets on.","zh":"他知道的比他表現出來的要多。"},{"en":"Do you know anyone in that city?","zh":"你在那個城市認識任何人嗎？"},{"en":"I just know — sometimes you just feel it.","zh":"我就是知道——有時候你就是有那種感覺。"},{"en":"She knows exactly who she is — rare and admirable.","zh":"她清楚地知道自己是誰——罕見且令人欽佩。"},{"en":"How do you know so much about this?","zh":"你怎麼知道這麼多關於這個的事情？"},{"en":"You will know when you are ready.","zh":"你準備好的時候你會知道的。"},{"en":"I know it is hard but it will get easier.","zh":"我知道很難，但它會變得更容易的。"}]},{"word":"time","pos":"noun","chinese":"時間；次數","level":"A1","sentences":[{"en":"Time flies when you are having fun.","zh":"開心的時候時間過得飛快。"},{"en":"I do not have time for drama right now.","zh":"我現在沒時間處理麻煩事。"},{"en":"What time does the café open?","zh":"咖啡廳幾點開門？"},{"en":"She makes time for the people she loves.","zh":"她為她愛的人騰出時間。"},{"en":"This is not the right time — let's talk later.","zh":"現在不是好時機——我們待會兒再說。"},{"en":"I had the time of my life at that concert.","zh":"我在那場演唱會度過了最美好的時光。"},{"en":"Time is the most valuable thing you can give someone.","zh":"時間是你能給予別人最珍貴的東西。"},{"en":"It is only a matter of time — be patient.","zh":"只是時間問題——要有耐心。"},{"en":"She arrived on time, as always.","zh":"她準時到了，一如既往。"},{"en":"I waste so much time scrolling without noticing.","zh":"我刷手機浪費了太多時間，卻沒有注意到。"}]},{"word":"day","pos":"noun","chinese":"天；日子","level":"A1","sentences":[{"en":"Today is a good day — I can feel it.","zh":"今天是個好日子——我能感覺到。"},{"en":"She counts down the days until her holiday.","zh":"她倒數距離假期還有幾天。"},{"en":"What are you doing later in the day?","zh":"你今天稍晚有什麼安排？"},{"en":"Some days are just harder than others — that is okay.","zh":"有些日子就是比其他日子難——沒關係。"},{"en":"He made my day with one small gesture.","zh":"他的一個小舉動讓我整天都很開心。"},{"en":"Day by day, things are getting better.","zh":"一天一天地，事情正在好轉。"},{"en":"I have not had a proper day off in weeks.","zh":"我已經好幾週沒有好好休息一天了。"},{"en":"She starts every day with ten minutes of quiet.","zh":"她每天以十分鐘的安靜開始。"},{"en":"That was one of the best days of my life.","zh":"那是我人生中最美好的日子之一。"},{"en":"End your day with gratitude — it changes everything.","zh":"用感恩結束你的一天——它改變一切。"}]},{"word":"year","pos":"noun","chinese":"年；年份","level":"A1","sentences":[{"en":"This year has been full of changes — good and bad.","zh":"今年充滿了變化——好的和壞的。"},{"en":"She has been working there for three years.","zh":"她已經在那裡工作了三年。"},{"en":"New Year, same me — but maybe slightly better.","zh":"新的一年，還是同樣的我——但也許稍微好一點。"},{"en":"The years go by faster the older you get.","zh":"年紀越大，歲月流逝越快。"},{"en":"I have not seen her in two years — I miss her.","zh":"我兩年沒見到她了——我很想念她。"},{"en":"This was the year I finally took that leap.","zh":"今年是我終於邁出那一步的一年。"},{"en":"He has grown so much in just one year.","zh":"他在短短一年內成長了這麼多。"},{"en":"Every year I set one big goal and focus on it.","zh":"每年我設定一個大目標，然後專注於它。"},{"en":"Next year, I want to travel to somewhere new.","zh":"明年，我想去一個新的地方旅行。"},{"en":"Some years shape you more than others.","zh":"有些年份比其他年份更塑造你。"}]},{"word":"place","pos":"noun","chinese":"地方；位置","level":"A1","sentences":[{"en":"This is my favourite place in the whole city.","zh":"這是整個城市裡我最喜歡的地方。"},{"en":"Do you know a good place to eat near here?","zh":"你知道附近有什麼好吃的地方嗎？"},{"en":"She always feels at home in that place.","zh":"她在那個地方總是感到自在。"},{"en":"I need a quiet place to think.","zh":"我需要一個安靜的地方思考。"},{"en":"That place holds so many memories for me.","zh":"那個地方對我來說有太多回憶。"},{"en":"He found a place that felt like it was made for him.","zh":"他找到了一個感覺像是為他而生的地方。"},{"en":"Is there still a place for me at the table?","zh":"桌子那裡還有我的位置嗎？"},{"en":"She travelled to a different place every year.","zh":"她每年去一個不同的地方旅行。"},{"en":"Your place in someone's life shows in how they talk about you.","zh":"你在某人生命中的位置，從他們談論你的方式就能看出來。"},{"en":"There is no better place to be than right here.","zh":"沒有比此刻所在更好的地方了。"}]},{"word":"name","pos":"noun/verb","chinese":"名字；命名","level":"A1","sentences":[{"en":"What is your name? I do not think we have met.","zh":"你叫什麼名字？我想我們還沒見過。"},{"en":"She named her cat after a character from her favourite book.","zh":"她用最喜歡的書中的角色給她的貓命名。"},{"en":"I am terrible with names — please remind me.","zh":"我記人名很差——請提醒我。"},{"en":"His name was on everyone's lips that day.","zh":"那天所有人都在說他的名字。"},{"en":"She made a name for herself in the industry.","zh":"她在業界為自己建立了名聲。"},{"en":"Can I get your name for the reservation?","zh":"我可以記下您的名字作為預約嗎？"},{"en":"A name can carry a whole story.","zh":"一個名字可以承載一整個故事。"},{"en":"He goes by a nickname — no one uses his real name.","zh":"他用暱稱，沒有人叫他的本名。"},{"en":"I finally put a name to the feeling I had been carrying.","zh":"我終於找到了一個詞來形容我一直懷抱的感受。"},{"en":"She named the project after something meaningful to her.","zh":"她用對她有意義的事物來命名這個項目。"}]},{"word":"home","pos":"noun","chinese":"家；回家","level":"A1","sentences":[{"en":"There is no place like home — especially after a long trip.","zh":"沒有任何地方比得上家——尤其是長途旅行後。"},{"en":"She feels most herself when she is at home.","zh":"她在家的時候最像自己。"},{"en":"I worked from home today and loved the quiet.","zh":"我今天在家工作，很喜歡那種安靜。"},{"en":"He made everywhere he lived feel like home.","zh":"他讓他住過的每個地方都像家。"},{"en":"Home is not a place — it is a feeling.","zh":"家不是一個地方——而是一種感覺。"},{"en":"I am heading home now — see you tomorrow.","zh":"我現在要回家了——明天見。"},{"en":"She called her mum the moment she got home.","zh":"她一回到家就打電話給她媽媽。"},{"en":"Make your home a space that restores you.","zh":"把你的家變成一個恢復你的空間。"},{"en":"He was homesick for the first time in his life.","zh":"他第一次在人生中感到思鄉。"},{"en":"Coming home to someone who loves you is everything.","zh":"回家有人愛你等著你，那就是一切。"}]},{"word":"friend","pos":"noun","chinese":"朋友；好友","level":"A1","sentences":[{"en":"She is the kind of friend who shows up unannounced with food.","zh":"她是那種突然出現帶著食物的朋友。"},{"en":"A good friend tells you when you have spinach in your teeth.","zh":"好朋友會告訴你牙齒上有菜葉。"},{"en":"I made my closest friends in the most unexpected places.","zh":"我在最意想不到的地方結交了最親密的朋友。"},{"en":"He is not just a colleague — he is a real friend.","zh":"他不只是同事——他是真正的朋友。"},{"en":"I need to call a friend. I miss real conversation.","zh":"我需要打電話給朋友，我想念真正的對話。"},{"en":"She has the gift of making everyone feel like her best friend.","zh":"她有讓所有人都感覺像是她最好朋友的天賦。"},{"en":"Old friends carry your history — cherish them.","zh":"老朋友承載著你的歷史——珍惜他們。"},{"en":"Making new friends as an adult is harder but worth it.","zh":"成年後交新朋友更難，但值得。"},{"en":"A friend who listens is worth more than one who advises.","zh":"善於傾聽的朋友比給建議的朋友更珍貴。"},{"en":"Be the kind of friend you wish you had.","zh":"成為你希望擁有的那種朋友。"}]},{"word":"money","pos":"noun","chinese":"錢；金錢","level":"A1","sentences":[{"en":"I do not have a lot of money but I spend it on things I love.","zh":"我沒有很多錢，但我把它花在我喜歡的事情上。"},{"en":"She saves money by cooking at home most nights.","zh":"她大多數晚上在家做飯來省錢。"},{"en":"Money does not buy happiness but it buys options.","zh":"金錢買不到快樂，但能買到選擇。"},{"en":"He spent all his money on experiences, not things.","zh":"他把所有的錢都花在體驗上，而不是物品。"},{"en":"I need to be smarter about where my money goes.","zh":"我需要更聰明地管理我的錢去了哪裡。"},{"en":"She earns good money but never shows it off.","zh":"她賺了不少錢，但從不炫耀。"},{"en":"Talking about money is still taboo in some cultures.","zh":"在一些文化中，談論金錢仍然是禁忌。"},{"en":"Time is more valuable than money — you cannot earn it back.","zh":"時間比金錢更有價值——你無法把它賺回來。"},{"en":"He lent me money without asking when I would pay it back.","zh":"他借了我錢，沒有問我什麼時候還。"},{"en":"I stopped buying things I did not need and saved more money.","zh":"我停止購買我不需要的東西，省了更多錢。"}]},{"word":"food","pos":"noun","chinese":"食物；飲食","level":"A1","sentences":[{"en":"Food is love in my family — every gathering has a big meal.","zh":"在我家，食物就是愛——每次聚會都有一頓大餐。"},{"en":"She photographs her food before eating — every single time.","zh":"她每次吃飯前都會先拍照。"},{"en":"Good food does not have to be complicated.","zh":"好的食物不必複雜。"},{"en":"He knows every good food spot in the city.","zh":"他知道城市裡每一個美食好去處。"},{"en":"I tried a food I could not name and it was the best thing I ever ate.","zh":"我試了一種我不知道名字的食物，那是我吃過最好吃的東西。"},{"en":"The best food is usually found in the simplest places.","zh":"最好的食物通常在最簡單的地方。"},{"en":"She grew up making food from scratch — no shortcuts.","zh":"她從小就從頭開始做飯——沒有捷徑。"},{"en":"Food from home always tastes different when you are far away.","zh":"在外地的時候，家鄉的食物總是嚐起來不同了。"},{"en":"I connect with people over food more than anything.","zh":"我通過食物和人們建立聯繫，超過其他任何事情。"},{"en":"Good food shared with good people is one of life's great joys.","zh":"與好人分享好食物是人生的一大樂趣。"}]},{"word":"water","pos":"noun","chinese":"水；水分","level":"A1","sentences":[{"en":"Drink more water. I know everyone says it but it works.","zh":"多喝水，我知道所有人都這樣說，但它確實有效。"},{"en":"She carries a water bottle everywhere — good habit.","zh":"她到處帶著水瓶——好習慣。"},{"en":"The sound of running water is so calming.","zh":"流水的聲音非常讓人平靜。"},{"en":"I forgot to water my plants and they are not happy.","zh":"我忘記給植物澆水，它們不高興了。"},{"en":"He drinks cold water first thing every morning.","zh":"他每天早上第一件事就是喝冷水。"},{"en":"Water under the bridge — I have forgiven and moved on.","zh":"已經過去的事了——我已經原諒，繼續前進了。"},{"en":"Nothing beats a glass of cold water on a hot day.","zh":"在炎熱的日子裡，沒有什麼比一杯冷水更好了。"},{"en":"She swims in open water every weekend.","zh":"她每個週末在開放水域游泳。"},{"en":"Stay hydrated — your brain needs water to function.","zh":"保持補水——你的大腦需要水才能運作。"},{"en":"The river looked so still and peaceful in the early morning.","zh":"早晨的河流看起來如此平靜安詳。"}]},{"word":"work","pos":"noun/verb","chinese":"工作；運作","level":"A1","sentences":[{"en":"I love what I do — not everyone can say that.","zh":"我喜歡我所做的事——不是每個人都能這樣說。"},{"en":"Work hard but not so hard you forget why you started.","zh":"努力工作，但不要努力到忘記你為什麼開始。"},{"en":"She works best in the early morning hours.","zh":"她在清晨工作效率最高。"},{"en":"I am not working this weekend — full switch off.","zh":"我這個週末不工作——完全關機。"},{"en":"Hard work pays off — not always immediately, but it does.","zh":"努力工作會有回報——不一定立刻，但它確實會。"},{"en":"He makes everything he does look effortless.","zh":"他讓他所做的一切看起來毫不費力。"},{"en":"Work is important but it is not your whole identity.","zh":"工作很重要，但它不是你全部的身份。"},{"en":"She worked through the problem step by step.","zh":"她一步一步地解決了那個問題。"},{"en":"That plan is not going to work — let me suggest something else.","zh":"那個計畫不會奏效——讓我提議別的方法。"},{"en":"Working with great people makes all the difference.","zh":"和優秀的人一起工作會帶來巨大的不同。"}]},{"word":"school","pos":"noun","chinese":"學校；上學","level":"A1","sentences":[{"en":"She loved school — every subject was an adventure.","zh":"她喜歡上學——每個科目都是一場冒險。"},{"en":"I learned more outside of school than inside it.","zh":"我在校外學到的比在校內更多。"},{"en":"He went back to school at forty and loved it.","zh":"他四十歲回到學校，並且很喜歡。"},{"en":"School teaches you information. Life teaches you wisdom.","zh":"學校教你知識，生活教你智慧。"},{"en":"She was always the first one at school.","zh":"她總是最早到學校的人。"},{"en":"My best memories from school are the friendships.","zh":"我學校裡最美好的記憶是那些友誼。"},{"en":"Old school methods sometimes work better than modern ones.","zh":"傳統方法有時比現代方法更有效。"},{"en":"He graduated from school and had no idea what to do next.","zh":"他從學校畢業，不知道接下來要做什麼。"},{"en":"School is where you learn how to learn.","zh":"學校是你學習如何學習的地方。"},{"en":"She never let school get in the way of her education.","zh":"她從不讓學校妨礙她的教育。"}]},{"word":"book","pos":"noun/verb","chinese":"書；預約","level":"A1","sentences":[{"en":"She reads a book a week — I admire that dedication.","zh":"她每週讀一本書——我欽佩那種投入。"},{"en":"I judged a book by its cover and was completely wrong.","zh":"我以貌取書，結果完全錯了。"},{"en":"Can I book a table for two for Friday evening?","zh":"我可以預訂週五晚上兩人桌嗎？"},{"en":"He has a book recommendation for every mood.","zh":"他有適合每種心情的書籍推薦。"},{"en":"The book changed how I see the world.","zh":"那本書改變了我看世界的方式。"},{"en":"I am so booked this week — no free evenings.","zh":"我這週排得很滿——沒有空閒的晚上。"},{"en":"She wrote a book about her experience and it resonated with millions.","zh":"她寫了一本關於她經歷的書，引起了數百萬人的共鳴。"},{"en":"Some books find you at exactly the right time.","zh":"有些書在恰好合適的時候找到了你。"},{"en":"I cannot put this book down — it is that good.","zh":"我放不下這本書——它就是這麼好看。"},{"en":"Book the trip first — figure the rest out after.","zh":"先訂機票——其他的以後再說。"}]},{"word":"music","pos":"noun","chinese":"音樂","level":"A1","sentences":[{"en":"Music is the only thing that makes my commute enjoyable.","zh":"音樂是唯一讓我的通勤變得愉快的事情。"},{"en":"She puts on music when she needs to think.","zh":"她需要思考時會放音樂。"},{"en":"That song is the soundtrack to a whole chapter of my life.","zh":"那首歌是我人生某個篇章的配樂。"},{"en":"Good music makes ordinary moments feel cinematic.","zh":"好音樂讓普通的時刻感覺像電影場景。"},{"en":"He makes music in his spare time — purely for joy.","zh":"他業餘時間製作音樂——純粹是為了快樂。"},{"en":"Music has a way of saying what words cannot.","zh":"音樂有一種方式說出語言無法表達的東西。"},{"en":"I discovered this song at the right moment — it healed something.","zh":"我在正確的時刻發現了這首歌——它治癒了什麼。"},{"en":"She grew up surrounded by music and it shows.","zh":"她在音樂環繞中長大，這從她身上看得出來。"},{"en":"Live music hits differently — you feel it in your whole body.","zh":"現場音樂的感覺完全不同——你能全身感受到它。"},{"en":"Some music takes you straight back to a specific memory.","zh":"有些音樂直接帶你回到一段特定的記憶。"}]},{"word":"family","pos":"noun","chinese":"家人；家庭","level":"A1","sentences":[{"en":"Family is not always blood — it is who shows up for you.","zh":"家人不一定是血親——而是那些為你出現的人。"},{"en":"She calls her whole family every Sunday morning.","zh":"她每個週日早上打電話給全家人。"},{"en":"My family is chaotic but I would not trade it.","zh":"我的家庭很混亂，但我不會用它換任何東西。"},{"en":"He moved cities but stayed close to his family in spirit.","zh":"他搬去了另一個城市，但在精神上仍然和家人很親近。"},{"en":"Family gatherings are loud, messy and the best thing ever.","zh":"家庭聚會吵鬧、混亂，卻是最美好的事情。"},{"en":"She built a chosen family when her biological one was not there.","zh":"當她的原生家庭不在時，她建立了一個自己選擇的家庭。"},{"en":"Family is where you learn your first lessons about love.","zh":"家庭是你學習關於愛的第一課的地方。"},{"en":"He takes family time seriously — phone goes away at dinner.","zh":"他認真對待家庭時間——晚餐時手機收起來。"},{"en":"Some family relationships take work — that is normal.","zh":"一些家庭關係需要努力維繫——這是正常的。"},{"en":"The family you choose matters just as much as the one you are born into.","zh":"你選擇的家人和你出生的家庭一樣重要。"}]},{"word":"word","pos":"noun","chinese":"詞；單詞；話","level":"A1","sentences":[{"en":"She has a way with words — everything she says lands perfectly.","zh":"她有駕馭語言的天賦——她說的每句話都恰到好處。"},{"en":"I do not always have the right words but I try.","zh":"我不總是能找到合適的詞，但我會努力。"},{"en":"One kind word can turn someone's whole day around.","zh":"一句善意的話可以改變某人的整天。"},{"en":"She kept her word — that is rare these days.","zh":"她守信了——這在今天是難得的。"},{"en":"I learned a new word today: liminal.","zh":"我今天學了一個新詞：臨界。"},{"en":"His words stayed with me long after the conversation ended.","zh":"他說的話在對話結束後很久還留在我心裡。"},{"en":"Actions speak louder than words — but words still matter.","zh":"行動勝於語言——但語言仍然重要。"},{"en":"She always finds the exact word she needs.","zh":"她總是能找到她需要的確切詞語。"},{"en":"Words can heal or harm — choose them carefully.","zh":"話語可以治癒或傷害——要謹慎選擇。"},{"en":"I cannot find the words — but you already know.","zh":"我找不到語言——但你已經知道了。"}]},{"word":"life","pos":"noun","chinese":"生命；生活","level":"A1","sentences":[{"en":"Life is short — spend it on things that matter.","zh":"生命短暫——把它花在重要的事情上。"},{"en":"She approaches life with curiosity and openness.","zh":"她以好奇心和開放的態度面對生活。"},{"en":"This is not the life I planned but it is mine and I love it.","zh":"這不是我計畫的生活，但它是我的，我愛它。"},{"en":"Real life is messier than social media suggests.","zh":"真實的生活比社交媒體展示的要混亂得多。"},{"en":"He lives his life without apologising for who he is.","zh":"他過著不為自己是誰而道歉的生活。"},{"en":"Life teaches you lessons school never could.","zh":"生活教你學校永遠無法教的課。"},{"en":"Sometimes life surprises you in the best possible way.","zh":"有時候生活會以最好的方式給你驚喜。"},{"en":"She made the most of the life she had.","zh":"她充分利用了她所擁有的生活。"},{"en":"Life is a collection of small moments — make them count.","zh":"生活是由一個個小時刻組成的——讓它們有意義。"},{"en":"The good life is not about having everything — it is about enjoying what you have.","zh":"美好的生活不是擁有一切——而是享受你所擁有的。"}]},{"word":"world","pos":"noun","chinese":"世界；全球","level":"A1","sentences":[{"en":"She wants to see as much of the world as possible.","zh":"她想看盡世界上盡可能多的地方。"},{"en":"The world is so much bigger than the problems in front of you.","zh":"世界比你面前的問題大得多。"},{"en":"He created his own world through his writing.","zh":"他通過寫作創造了自己的世界。"},{"en":"In a perfect world, everyone would be kind.","zh":"在一個完美的世界裡，每個人都會善良。"},{"en":"She changed her world by changing her perspective.","zh":"她通過改變她的視角改變了她的世界。"},{"en":"That book opened up a whole new world to me.","zh":"那本書為我打開了一個全新的世界。"},{"en":"The world looks different when you travel.","zh":"旅行時世界看起來不一樣。"},{"en":"He means the world to the people who love him.","zh":"他對愛他的人來說意味著一切。"},{"en":"You do not have to change the whole world — just yours.","zh":"你不必改變整個世界——只需改變你的世界。"},{"en":"She sees the best in people and the world.","zh":"她看到人和世界最好的一面。"}]},{"word":"person","pos":"noun","chinese":"人；個人","level":"A1","sentences":[{"en":"She is the most genuine person I have ever met.","zh":"她是我遇到過的最真實的人。"},{"en":"He is a person who shows up — every single time.","zh":"他是一個每次都會出現的人。"},{"en":"Every person has a story worth listening to.","zh":"每個人都有值得傾聽的故事。"},{"en":"I am a morning person — completely useless after ten.","zh":"我是一個早晨型的人——十點之後完全沒用了。"},{"en":"She grew into the person she always wanted to be.","zh":"她成長為她一直想成為的人。"},{"en":"The wrong person in your life can drain everything.","zh":"生命中錯誤的人可以耗盡一切。"},{"en":"He is such a good person — always thinking of others.","zh":"他真的是個好人——總是為別人著想。"},{"en":"Becoming a better person takes time and honesty.","zh":"成為更好的人需要時間和誠實。"},{"en":"She is a people person — thrives in social settings.","zh":"她是一個社交型的人——在社交環境中如魚得水。"},{"en":"You cannot be everything to every person.","zh":"你無法對每個人都做到一切。"}]},{"word":"way","pos":"noun","chinese":"方式；路","level":"A1","sentences":[{"en":"She has a way of making everything look elegant.","zh":"她有讓一切看起來優雅的方式。"},{"en":"There is no one right way to do this.","zh":"沒有唯一正確的方式來做這件事。"},{"en":"Can you show me the way to the station?","zh":"你能告訴我去車站的路嗎？"},{"en":"He does things his own way and it works.","zh":"他用自己的方式做事，而且奏效。"},{"en":"I lost my way for a bit but I found it again.","zh":"我迷失了一段時間，但我又找到了方向。"},{"en":"This is the long way around but the views are worth it.","zh":"這是一條繞遠路，但風景值得。"},{"en":"She found a way when there seemed to be none.","zh":"她在似乎沒有出路的時候找到了方法。"},{"en":"By the way, have you heard the news?","zh":"順便問一下，你聽到那個消息了嗎？"},{"en":"Some things have a way of working out on their own.","zh":"有些事情有自己解決的方式。"},{"en":"He found his way in life the hard way — but he found it.","zh":"他用艱難的方式找到了人生的方向——但他找到了。"}]},{"word":"thing","pos":"noun","chinese":"東西；事情","level":"A1","sentences":[{"en":"The funny thing is, I almost did not go.","zh":"有趣的是，我差點沒有去。"},{"en":"She has this thing about being early — always first.","zh":"她有個習慣就是早到——總是第一個。"},{"en":"One thing at a time — slow down.","zh":"一次一件事——放慢腳步。"},{"en":"The best things in life are not things.","zh":"生命中最好的事情都不是物品。"},{"en":"That is the thing about him — he always surprises you.","zh":"這就是他的特點——他總是給你驚喜。"},{"en":"I collect small things that remind me of good moments.","zh":"我收集能讓我想起美好時刻的小東西。"},{"en":"The whole thing was a mess but we got through it.","zh":"整件事一團糟，但我們撐過來了。"},{"en":"She does not need things — she needs experiences.","zh":"她不需要物品——她需要體驗。"},{"en":"Next thing I knew, it was midnight.","zh":"一眨眼，已經午夜了。"},{"en":"Little things add up to big things over time.","zh":"小事情隨著時間累積成大事情。"}]},{"word":"hand","pos":"noun/verb","chinese":"手；交給","level":"A1","sentences":[{"en":"She always has a helping hand ready.","zh":"她總是隨時準備好伸出援手。"},{"en":"He held her hand and said nothing — that was enough.","zh":"他握住她的手什麼都沒說——那已經足夠了。"},{"en":"Give me a hand with this — it is too heavy.","zh":"幫我一下——這太重了。"},{"en":"She works with her hands every day — baker, crafter, maker.","zh":"她每天用雙手工作——麵包師、工藝師、製作者。"},{"en":"The situation got out of hand before anyone noticed.","zh":"情況在任何人注意到之前就失控了。"},{"en":"I have time on my hands this week — anything I can help with?","zh":"我這週有空——有什麼我能幫忙的嗎？"},{"en":"Old hands know things that cannot be taught in school.","zh":"老前輩知道一些學校教不了的東西。"},{"en":"She handed me the note without saying a word.","zh":"她把紙條遞給我，一句話都沒說。"},{"en":"Can you hand that to me? It is just out of reach.","zh":"你能把那個遞給我嗎？我就是夠不到。"},{"en":"Every great thing was built by human hands.","zh":"每一件偉大的事物都是由人的雙手建造的。"}]},{"word":"eye","pos":"noun","chinese":"眼睛；眼光","level":"A1","sentences":[{"en":"She has an eye for detail that no one else catches.","zh":"她有一種沒有人能比得上的細節眼光。"},{"en":"He could not take his eyes off the view.","zh":"他捨不得移開對那風景的目光。"},{"en":"I caught her eye across the room and smiled.","zh":"我在房間另一頭和她對上了眼，微笑了。"},{"en":"Keep an eye on this — it could be important.","zh":"注意這個——它可能很重要。"},{"en":"She sees the world through kind eyes.","zh":"她用善良的眼光看世界。"},{"en":"That painting caught my eye the moment I walked in.","zh":"那幅畫在我一走進去就吸引了我的目光。"},{"en":"In the eyes of the people who love you, you are enough.","zh":"在愛你的人眼中，你已經足夠了。"},{"en":"He had a twinkle in his eye — always up to something.","zh":"他眼睛裡有一種光芒——總是有些計謀。"},{"en":"She opened her eyes and saw things differently.","zh":"她睜開眼睛，以不同的方式看待事情。"},{"en":"I need to rest my eyes — too much screen time.","zh":"我需要讓眼睛休息——螢幕時間太多了。"}]},{"word":"heart","pos":"noun","chinese":"心臟；心","level":"A1","sentences":[{"en":"She has such a big heart — always giving.","zh":"她有一顆很大的心——總是在給予。"},{"en":"Follow your heart but take your brain with you.","zh":"跟隨你的心，但帶上你的大腦。"},{"en":"That song goes straight to my heart every time.","zh":"那首歌每次都直接打動我的心。"},{"en":"He speaks from the heart and people feel it.","zh":"他發自內心地說話，人們能感受到。"},{"en":"She put her whole heart into everything she made.","zh":"她把全心全意投入到她做的每一件事中。"},{"en":"A broken heart heals — it just takes time.","zh":"心碎會癒合——只是需要時間。"},{"en":"His heart was in the right place even when he got it wrong.","zh":"即使他做錯了，他的出發點是好的。"},{"en":"At the heart of it, we all want to feel seen.","zh":"歸根結底，我們都想要被看見。"},{"en":"She learned to listen to her heart over her fears.","zh":"她學會了傾聽自己的心而不是恐懼。"},{"en":"Home is wherever your heart is.","zh":"家在你心之所在。"}]},{"word":"mind","pos":"noun/verb","chinese":"心靈；想法；介意","level":"A1","sentences":[{"en":"She has a creative mind — always solving things differently.","zh":"她有一個創意的心靈——總是以不同的方式解決問題。"},{"en":"I cannot get it out of my mind.","zh":"我無法把它從腦海中趕走。"},{"en":"Do you mind if I sit here?","zh":"你介意我坐這裡嗎？"},{"en":"He keeps an open mind — rare and wonderful.","zh":"他保持開放的心態——難得而美好。"},{"en":"Never mind — it does not matter now.","zh":"算了——現在不重要了。"},{"en":"She changed her mind and I respected that.","zh":"她改變了主意，我尊重這一點。"},{"en":"Your mind is your most powerful tool — use it well.","zh":"你的心靈是你最強大的工具——好好使用它。"},{"en":"I spoke my mind and felt so much lighter.","zh":"我說出了心裡話，感覺輕鬆多了。"},{"en":"A calm mind makes better decisions.","zh":"平靜的心靈做出更好的決定。"},{"en":"She made up her mind and never looked back.","zh":"她下定了決心，再也沒有回頭看。"}]},{"word":"body","pos":"noun","chinese":"身體；群體","level":"A1","sentences":[{"en":"Listen to your body — it knows more than you think.","zh":"傾聽你的身體——它知道的比你想的更多。"},{"en":"She takes care of her body with movement and rest.","zh":"她通過運動和休息照顧她的身體。"},{"en":"Your body carries you through every experience — thank it.","zh":"你的身體帶你經歷每一段體驗——感謝它。"},{"en":"He learned to be comfortable in his own body.","zh":"他學會了對自己的身體感到自在。"},{"en":"Everybody reacts to stress differently — that is normal.","zh":"每個人對壓力的反應都不同——這是正常的。"},{"en":"She nourishes her body with food that makes her feel good.","zh":"她用讓她感覺良好的食物滋養身體。"},{"en":"Your body language says more than your words sometimes.","zh":"你的身體語言有時說的比你的話語更多。"},{"en":"Keep moving — a body in motion stays in motion.","zh":"保持運動——動起來的身體會持續運動。"},{"en":"She donated her body to science — a final act of generosity.","zh":"她把遺體捐給了科學——最後一個慷慨的行為。"},{"en":"The body keeps score — take care of your mental health too.","zh":"身體會記分——也要照顧好你的心理健康。"}]},{"word":"door","pos":"noun","chinese":"門；機會","level":"A1","sentences":[{"en":"She walked through the door and the room lit up.","zh":"她走進門，整個房間都亮了起來。"},{"en":"Close the door behind you — it is cold outside.","zh":"關上門——外面很冷。"},{"en":"He always holds the door for others — small but meaningful.","zh":"他總是為別人扶門——小事但有意義。"},{"en":"This opportunity is a door — open it.","zh":"這個機會是一扇門——打開它。"},{"en":"A closed door is not always a rejection — sometimes it is a redirect.","zh":"關閉的門並不總是拒絕——有時是重新導向。"},{"en":"She knocked on every door before the right one opened.","zh":"她敲了每一扇門，直到正確的一扇打開。"},{"en":"Next door neighbours can become lifelong friends.","zh":"隔壁鄰居可以成為一輩子的朋友。"},{"en":"When one door closes, another opens — believe it.","zh":"當一扇門關閉，另一扇門就會打開——相信它。"},{"en":"He left the door open — literally and figuratively.","zh":"他讓門保持開著——字面上和比喻上都是。"},{"en":"The door to change is always unlocked — you just have to turn the handle.","zh":"改變之門永遠是開著的——你只需要轉動門把。"}]},{"word":"light","pos":"noun/adjective/verb","chinese":"光；輕的；點燃","level":"A1","sentences":[{"en":"She turns on a lamp when she reads — soft light is best.","zh":"她閱讀時會打開一盞燈——柔和的光線最好。"},{"en":"Good light transforms how a place feels.","zh":"好的光線改變了一個地方的感覺。"},{"en":"He is the light in every room he enters.","zh":"他是他進入的每個房間裡的光。"},{"en":"Travel light — you do not need as much as you think.","zh":"輕裝旅行——你需要的沒有你想的那麼多。"},{"en":"Can you light the candles? I love the atmosphere.","zh":"你能點燃蠟燭嗎？我喜歡那種氣氛。"},{"en":"She saw things in a new light after their conversation.","zh":"他們對話後，她以新的眼光看待事物。"},{"en":"The morning light is my favourite time to take photos.","zh":"早晨的光線是我最喜歡拍照的時刻。"},{"en":"Make it light — this does not have to be so serious.","zh":"讓它輕鬆一點——這不必那麼嚴肅。"},{"en":"He was the light at the end of a very dark tunnel.","zh":"他是一條非常黑暗隧道盡頭的光。"},{"en":"At the end of the day, she chose lightness over heaviness.","zh":"在一天結束時，她選擇了輕盈而非沉重。"}]},{"word":"night","pos":"noun","chinese":"夜晚；晚上","level":"A1","sentences":[{"en":"Late nights are my most creative hours.","zh":"深夜是我最有創意的時間。"},{"en":"She loves the quiet of a city at night.","zh":"她喜歡城市夜晚的安靜。"},{"en":"Good night — I hope tomorrow is kinder.","zh":"晚安——希望明天更加溫柔。"},{"en":"He stayed up all night to finish the project.","zh":"他熬了一整夜完成那個項目。"},{"en":"Some nights I just want to sit by the window and think.","zh":"有些晚上我只是想坐在窗邊思考。"},{"en":"That night changed everything — in the best way.","zh":"那個夜晚改變了一切——以最好的方式。"},{"en":"She sleeps with the window open on warm nights.","zh":"在溫暖的夜晚，她開著窗睡覺。"},{"en":"The night sky here is incredible — so many stars.","zh":"這裡的夜空令人難以置信——那麼多星星。"},{"en":"Last night was one of those perfect evenings.","zh":"昨晚是那種完美的夜晚之一。"},{"en":"Night owls and early birds — both are valid.","zh":"夜貓子和早起的人——都是有效的生活方式。"}]},{"word":"room","pos":"noun","chinese":"房間；空間","level":"A1","sentences":[{"en":"She decorated her room to feel like a sanctuary.","zh":"她把房間裝飾得像一個聖所。"},{"en":"Is there room for one more at the table?","zh":"桌子旁邊還有多一個人的位子嗎？"},{"en":"He fills every room with his laugh.","zh":"他的笑聲充滿了每個房間。"},{"en":"There is always room to grow — in any area of life.","zh":"在生活的任何領域，總有成長的空間。"},{"en":"She made room in her schedule for rest.","zh":"她在日程中為休息騰出了空間。"},{"en":"Reading in a warm room on a rainy day is perfect.","zh":"在雨天的溫暖房間裡讀書是完美的。"},{"en":"He left the room before the argument could escalate.","zh":"他在爭論升級之前離開了房間。"},{"en":"Clean room, clear mind — there is definitely truth to that.","zh":"整潔的房間，清晰的心智——這確實有道理。"},{"en":"She saved room for dessert — always.","zh":"她總是留著肚子吃甜點。"},{"en":"Give yourself room to breathe — do not overschedule.","zh":"給自己喘息的空間——不要把日程排得太滿。"}]},{"word":"city","pos":"noun","chinese":"城市；都市","level":"A1","sentences":[{"en":"She fell in love with the city from the first taxi ride.","zh":"她從第一次坐計程車就愛上了這座城市。"},{"en":"Living in a big city is exciting and exhausting in equal measure.","zh":"住在大城市既令人興奮又令人疲憊，兩者兼而有之。"},{"en":"He knows every hidden gem in the city.","zh":"他知道城市裡每一個隱藏的寶藏。"},{"en":"The city at sunrise is a completely different animal.","zh":"日出時的城市是完全不同的景象。"},{"en":"She misses her home city every time she smells the food.","zh":"每次聞到那種食物的味道，她都會想念她的故鄉城市。"},{"en":"City life is not for everyone — and that is okay.","zh":"城市生活不適合所有人——這沒關係。"},{"en":"He explored a new city for three days without a plan.","zh":"他花了三天沒有計畫地探索一座新城市。"},{"en":"The city never sleeps but I need to.","zh":"城市永不入睡，但我需要。"},{"en":"She discovered her favourite café in a city she had never planned to visit.","zh":"她在一個她從未計畫參觀的城市發現了她最喜歡的咖啡廳。"},{"en":"Every city has a personality — I love finding it.","zh":"每個城市都有自己的個性——我喜歡發現它。"}]},{"word":"phone","pos":"noun","chinese":"電話；手機","level":"A1","sentences":[{"en":"My phone died at the worst possible moment.","zh":"我的手機在最糟糕的時刻沒電了。"},{"en":"She puts her phone away at dinner — I respect that.","zh":"她吃飯時把手機收起來——我很尊重這一點。"},{"en":"Can I use your phone? Mine has no signal.","zh":"我可以用你的手機嗎？我的沒有信號。"},{"en":"He talks on the phone while walking — always multitasking.","zh":"他一邊走路一邊打電話——總是在多工。"},{"en":"I dropped my phone and held my breath.","zh":"我把手機摔了，屏住呼吸。"},{"en":"She finally answered the phone after ten missed calls.","zh":"她在十個未接來電後終於接了電話。"},{"en":"The first thing I do every morning is check my phone — I want to change that.","zh":"我每天早上做的第一件事就是查看手機——我想改變這一點。"},{"en":"He left his phone at home on purpose and felt so free.","zh":"他故意把手機留在家裡，感到非常自由。"},{"en":"She called instead of texting — that felt thoughtful.","zh":"她選擇打電話而不是發訊息——這讓人感到貼心。"},{"en":"A phone-free evening once a week makes a huge difference.","zh":"每週一個不用手機的晚上會帶來巨大的改變。"}]},{"word":"car","pos":"noun","chinese":"汽車；車","level":"A1","sentences":[{"en":"She loves road trips — the car is her happy place.","zh":"她喜歡公路旅行——車是她的快樂場所。"},{"en":"He takes care of his car like it is family.","zh":"他照顧他的車就像家人一樣。"},{"en":"I take the bus instead of the car when I can.","zh":"我盡量坐公車而不開車。"},{"en":"The car broke down on the motorway — worst timing.","zh":"車在高速公路上拋錨了——最糟糕的時機。"},{"en":"She sang at the top of her lungs in the car alone.","zh":"她獨自在車裡放聲高唱。"},{"en":"His car is old but he says it has character.","zh":"他的車很舊，但他說它有個性。"},{"en":"Car journeys with good company and music — pure joy.","zh":"和好伴侶、好音樂的車程——純粹的快樂。"},{"en":"Parking in this city is a nightmare.","zh":"在這個城市停車是一場噩夢。"},{"en":"She drives the same car for ten years — why change what works?","zh":"她開了同一輛車十年——為什麼要改變有效的東西呢？"},{"en":"The car ride home was the quietest and most peaceful part of my day.","zh":"回家的車程是我一天中最安靜、最平靜的部分。"}]},{"word":"colour","pos":"noun","chinese":"顏色；色彩","level":"A1","sentences":[{"en":"She wears colour boldly and it suits her perfectly.","zh":"她大膽地穿著彩色，非常適合她。"},{"en":"The autumn colours here are breathtaking.","zh":"這裡的秋天色彩令人嘆為觀止。"},{"en":"He sees colour in places others miss.","zh":"他在別人錯過的地方看到色彩。"},{"en":"What colour should I paint this wall?","zh":"我應該把這面牆刷成什麼顏色？"},{"en":"She painted her bedroom a deep green and loved it.","zh":"她把臥室刷成深綠色，非常喜歡。"},{"en":"Colours affect your mood more than you realise.","zh":"顏色對你情緒的影響比你意識到的更大。"},{"en":"His personality adds colour to every group he joins.","zh":"他的個性為他加入的每個群體增添了色彩。"},{"en":"She added a pop of colour to an all-neutral outfit.","zh":"她在全中性色的服裝上加了一抹亮色。"},{"en":"That photo has beautiful, muted colours.","zh":"那張照片有美麗的、柔和的顏色。"},{"en":"Life is more colourful with the right people in it.","zh":"有了對的人，生活會更加多彩。"}]},{"word":"age","pos":"noun","chinese":"年齡；時代","level":"A1","sentences":[{"en":"Age is just a number — it is how you feel that matters.","zh":"年齡只是一個數字——感覺才是重要的。"},{"en":"She discovered her passion at an age when others retire.","zh":"她在別人退休的年齡發現了她的熱情。"},{"en":"He acts his age sometimes and forgets it other times.","zh":"他有時候表現得很成熟，有時候又忘記自己的年紀。"},{"en":"People of all ages can learn new things.","zh":"所有年齡的人都可以學習新事物。"},{"en":"What age were you when you realised what you wanted to do?","zh":"你幾歲的時候意識到了你想做什麼？"},{"en":"She looks younger than her age — she credits joy.","zh":"她看起來比她的年齡更年輕——她說這歸功於快樂。"},{"en":"In this day and age, information is everywhere.","zh":"在這個時代，信息無處不在。"},{"en":"Every age has its own beauty — even the hard ones.","zh":"每個年齡都有自己的美麗——即使是艱難的年齡。"},{"en":"He started over at fifty — age is just a starting point.","zh":"他在五十歲重新開始——年齡只是一個起點。"},{"en":"You are never too old or too young to follow your instincts.","zh":"你永遠不會太老或太年輕去跟隨你的直覺。"}]},{"word":"idea","pos":"noun","chinese":"想法；主意","level":"A1","sentences":[{"en":"That is a brilliant idea — why did I not think of that?","zh":"那是個好主意——我怎麼沒想到？"},{"en":"She always has an idea when everyone else is stuck.","zh":"當其他人都卡住時，她總有一個想法。"},{"en":"I had an idea in the shower — naturally.","zh":"我在淋浴時有了一個想法——當然。"},{"en":"The idea started small and grew into something huge.","zh":"這個想法一開始很小，慢慢發展成了龐大的東西。"},{"en":"He never dismisses an idea before thinking it through.","zh":"他從不在深思熟慮之前就否定一個想法。"},{"en":"That idea is ahead of its time — come back to it.","zh":"那個想法超前了——之後再回來想。"},{"en":"She shared her idea nervously and it landed perfectly.","zh":"她緊張地分享了她的想法，結果非常成功。"},{"en":"I have no idea — let me find out and get back to you.","zh":"我不知道——讓我查一下再回覆你。"},{"en":"Good ideas need action — not just conversation.","zh":"好想法需要行動——不只是討論。"},{"en":"That idea changed the whole direction of the project.","zh":"那個想法改變了整個項目的方向。"}]},{"word":"answer","pos":"noun/verb","chinese":"答案；回答","level":"A1","sentences":[{"en":"She always has an answer — and it is usually right.","zh":"她總是有答案——通常都是對的。"},{"en":"I do not have all the answers and I have made peace with that.","zh":"我沒有所有答案，我已經接受了這一點。"},{"en":"Can you answer the phone? I am in the middle of something.","zh":"你能接電話嗎？我正在忙。"},{"en":"He thought about the question before answering.","zh":"他在回答之前思考了這個問題。"},{"en":"Not every question has a clean answer.","zh":"並非每個問題都有清晰的答案。"},{"en":"She answered honestly even when it was hard.","zh":"她誠實地回答，即使這很難。"},{"en":"The answer was in front of me the whole time.","zh":"答案一直就在我面前。"},{"en":"He does not answer messages right away — she respects that.","zh":"他不會立刻回覆訊息——她尊重這一點。"},{"en":"Sometimes the answer is just: I need more time.","zh":"有時候答案就是：我需要更多時間。"},{"en":"She found the answer by asking a better question.","zh":"她通過問一個更好的問題找到了答案。"}]},{"word":"improve","pos":"verb","chinese":"改善；提升","level":"A2","sentences":[{"en":"My English has improved a lot since I started using this app.","zh":"自從我開始使用這個 App，我的英文進步了很多。"},{"en":"She improved her cooking by watching videos every weekend.","zh":"她通過每週末看視頻提升了她的廚藝。"},{"en":"There is always room to improve — never stop learning.","zh":"總有進步的空間——永遠不要停止學習。"},{"en":"He improved his mood by going for a walk.","zh":"他通過散步改善了心情。"},{"en":"We can improve the plan — let me suggest some changes.","zh":"我們可以改進這個計畫——讓我提些修改意見。"},{"en":"She improved at a pace that surprised even herself.","zh":"她進步的速度甚至讓她自己都感到驚訝。"},{"en":"Improving one small habit changed everything.","zh":"改善一個小習慣改變了一切。"},{"en":"The weather is expected to improve by the weekend.","zh":"天氣預計到週末會改善。"},{"en":"He improved his posture and his confidence followed.","zh":"他改善了姿勢，自信隨之而來。"},{"en":"Consistent practice is the only way to improve.","zh":"持續練習是進步的唯一方式。"}]},{"word":"decide","pos":"verb","chinese":"決定；下決心","level":"A2","sentences":[{"en":"She decided to stop waiting and just go for it.","zh":"她決定不再等待，直接去做。"},{"en":"Have you decided what to order yet?","zh":"你決定好要點什麼了嗎？"},{"en":"He decided against it at the last minute.","zh":"他在最後一刻決定不做了。"},{"en":"Deciding what to wear takes me longer than it should.","zh":"決定穿什麼花的時間比應該花的要長。"},{"en":"I decided to be honest even if it was uncomfortable.","zh":"我決定誠實，即使這不舒服。"},{"en":"She made the decision and never second-guessed it.","zh":"她做了決定，從未後悔。"},{"en":"You decide how you respond — that is your power.","zh":"你決定你如何回應——那是你的力量。"},{"en":"He decided that today was the day he would start.","zh":"他決定今天就是他開始的那天。"},{"en":"When you cannot decide, flip a coin and notice your reaction.","zh":"當你無法決定時，拋硬幣，注意你的反應。"},{"en":"She decided the most important things first.","zh":"她首先決定最重要的事情。"}]},{"word":"explain","pos":"verb","chinese":"解釋；說明","level":"A2","sentences":[{"en":"Can you explain that again? I did not quite follow.","zh":"你能再解釋一遍嗎？我沒有完全理解。"},{"en":"She explained the concept simply and clearly.","zh":"她簡單清楚地解釋了這個概念。"},{"en":"I cannot explain how much that moment meant to me.","zh":"我無法解釋那個時刻對我的意義有多深。"},{"en":"He explained his thinking and suddenly everyone agreed.","zh":"他解釋了他的思路，突然間大家都同意了。"},{"en":"Can you explain why you made that decision?","zh":"你能解釋為什麼你做了那個決定嗎？"},{"en":"She explained it with patience and no frustration.","zh":"她耐心而不氣餒地解釋了。"},{"en":"I do not need to explain myself to everyone.","zh":"我不需要向所有人解釋自己。"},{"en":"He explained the situation and the tension dropped.","zh":"他解釋了情況，緊張氣氛消散了。"},{"en":"Some things are hard to explain but easy to feel.","zh":"有些事情很難解釋，但很容易感受到。"},{"en":"She asked him to explain — and he finally did.","zh":"她要他解釋——他終於開口了。"}]},{"word":"suggest","pos":"verb","chinese":"建議；暗示","level":"A2","sentences":[{"en":"Can I suggest something? Try it without sugar first.","zh":"我可以建議一件事嗎？先試試不加糖的。"},{"en":"She suggested they take the scenic route and they did.","zh":"她建議他們走景觀路線，他們照做了。"},{"en":"What would you suggest for someone visiting for the first time?","zh":"你對第一次來訪的人有什麼建議？"},{"en":"He suggested a compromise and everyone was satisfied.","zh":"他提議了一個妥協方案，所有人都滿意了。"},{"en":"I am not telling you what to do — just suggesting.","zh":"我不是在告訴你怎麼做——只是建議。"},{"en":"She suggested reading the book before watching the film.","zh":"她建議先讀書再看電影。"},{"en":"The data suggests that the plan needs adjusting.","zh":"數據顯示計畫需要調整。"},{"en":"He suggested an early start to avoid the crowds.","zh":"他建議早點出發以避開人潮。"},{"en":"I would suggest sleeping on it before deciding.","zh":"我建議先睡一覺再做決定。"},{"en":"What are you suggesting — that I was wrong?","zh":"你在暗示什麼——我錯了嗎？"}]},{"word":"agree","pos":"verb","chinese":"同意；贊成","level":"A2","sentences":[{"en":"I completely agree — you put it better than I could.","zh":"我完全同意——你說得比我好。"},{"en":"She agrees with the plan but wants to adjust the timeline.","zh":"她同意這個計畫，但想調整時間線。"},{"en":"We do not always agree and that is actually healthy.","zh":"我們並不總是同意，這其實是健康的。"},{"en":"He agreed reluctantly but came through in the end.","zh":"他勉強同意了，但最後還是做到了。"},{"en":"I hate to agree with him but he has a point.","zh":"我不想同意他，但他說得有道理。"},{"en":"They agreed to disagree — and the friendship survived.","zh":"他們同意各持己見——友誼因此得以延續。"},{"en":"She agreed to help before I even finished asking.","zh":"她在我問完之前就同意幫忙了。"},{"en":"Most people agree that kindness costs nothing.","zh":"大多數人同意善良不需要任何代價。"},{"en":"I agree with the principle but question the method.","zh":"我同意這個原則，但質疑這個方法。"},{"en":"He finally agreed and everyone moved forward.","zh":"他終於同意了，大家繼續前進。"}]},{"word":"disagree","pos":"verb","chinese":"不同意；有異議","level":"A2","sentences":[{"en":"I respectfully disagree — here is my perspective.","zh":"我尊重地表示不同意——這是我的看法。"},{"en":"She disagreed but did not argue — just stated her view calmly.","zh":"她不同意，但沒有爭吵——只是冷靜地表明了自己的觀點。"},{"en":"It is okay to disagree with someone you respect.","zh":"與你尊重的人意見不同是沒關係的。"},{"en":"We disagree on methods but agree on the goal.","zh":"我們在方法上有分歧，但在目標上達成共識。"},{"en":"He disagreed strongly but listened before responding.","zh":"他強烈反對，但在回應之前先傾聽了。"},{"en":"Healthy relationships survive disagreement.","zh":"健康的關係能夠承受分歧。"},{"en":"I completely disagree — let me explain why.","zh":"我完全不同意——讓我解釋原因。"},{"en":"She was not afraid to disagree with the majority.","zh":"她不害怕與多數人意見相左。"},{"en":"They disagreed in public but worked it out privately.","zh":"他們在公眾場合有分歧，但私下解決了。"},{"en":"Disagreement done right leads to better ideas.","zh":"正確地表達不同意見會帶來更好的想法。"}]},{"word":"promise","pos":"verb/noun","chinese":"承諾；保證","level":"A2","sentences":[{"en":"She always keeps her promises — that is rare.","zh":"她總是履行承諾——這很難得。"},{"en":"I promise I will call you when I land.","zh":"我保證我落地後會打電話給你。"},{"en":"He made a promise to himself and kept it for ten years.","zh":"他對自己許下了諾言，並保守了十年。"},{"en":"Do not make promises you cannot keep.","zh":"不要做你無法兌現的承諾。"},{"en":"She promised to be honest and she was.","zh":"她承諾要誠實，她做到了。"},{"en":"That young artist shows great promise.","zh":"那位年輕藝術家展現出了巨大的潛力。"},{"en":"I promised myself one thing: no more wasted time.","zh":"我答應自己一件事：不再浪費時間。"},{"en":"He broke his promise and it damaged the trust.","zh":"他違背了承諾，這損害了信任。"},{"en":"A promise made in the dark still counts in the light.","zh":"在黑暗中許下的承諾在光天化日之下同樣有效。"},{"en":"She did not promise the outcome — just the effort.","zh":"她沒有承諾結果——只承諾努力。"}]},{"word":"remember","pos":"verb","chinese":"記得；記住","level":"A2","sentences":[{"en":"I remember exactly where I was when I heard that news.","zh":"我確切地記得我聽到那個消息時在哪裡。"},{"en":"She remembers everyone's birthday — even without reminders.","zh":"她記得每個人的生日——即使沒有提醒。"},{"en":"Remember to drink water today — you always forget.","zh":"記得今天喝水——你總是忘記。"},{"en":"I want to remember this moment forever.","zh":"我想永遠記住這個時刻。"},{"en":"He remembered the important things even when life got busy.","zh":"即使生活變得忙碌，他也記住了重要的事情。"},{"en":"Do you remember the first time we met?","zh":"你記得我們第一次見面嗎？"},{"en":"She remembered everything but pretended to forget.","zh":"她記得一切，但假裝忘記了。"},{"en":"Remember: you have come so far already.","zh":"記住：你已經走了很遠了。"},{"en":"I barely remember what I had for breakfast.","zh":"我幾乎不記得我早餐吃了什麼。"},{"en":"He is remembered for his kindness more than anything.","zh":"他最讓人記住的是他的善良。"}]},{"word":"forget","pos":"verb","chinese":"忘記；遺忘","level":"A2","sentences":[{"en":"I forgot my umbrella — again.","zh":"我又忘了帶雨傘。"},{"en":"She forgot his name the moment he said it.","zh":"她在他說出名字的那一刻就忘記了。"},{"en":"Forget it — do not waste energy on that.","zh":"算了——不要在那件事上浪費精力。"},{"en":"He forgot her birthday and spent a week making it up.","zh":"他忘記了她的生日，花了一週時間彌補。"},{"en":"I never forget a face but always forget a name.","zh":"我從不忘記一張臉，但總是忘記名字。"},{"en":"She forgot to eat when she was deep in a project.","zh":"她在深入一個項目時忘記了吃飯。"},{"en":"Forget the past — today is what matters.","zh":"忘掉過去——今天才是重要的。"},{"en":"He could not forget what she said even if he tried.","zh":"即使他努力嘗試，他也無法忘記她說的話。"},{"en":"Some things are better forgotten.","zh":"有些事情最好被遺忘。"},{"en":"She reminded me of something I had almost forgotten.","zh":"她提醒了我一件我幾乎忘記的事情。"}]},{"word":"enjoy","pos":"verb","chinese":"享受；喜歡","level":"A2","sentences":[{"en":"She genuinely enjoys the process, not just the result.","zh":"她真心享受過程，而不只是結果。"},{"en":"Do you enjoy cooking or is it just a chore?","zh":"你喜歡做飯還是它只是一件雜務？"},{"en":"I enjoy long walks without a destination.","zh":"我喜歡沒有目的地的長距離步行。"},{"en":"He enjoys being alone just as much as being with people.","zh":"他喜歡獨處，就像喜歡和人在一起一樣。"},{"en":"Enjoy this moment — it will not last forever.","zh":"享受這個時刻——它不會永遠持續。"},{"en":"She enjoys the little things more than most.","zh":"她比大多數人更享受小事情。"},{"en":"I enjoyed every second of that holiday.","zh":"我享受了那次假期的每一秒。"},{"en":"He enjoys learning but hates being tested.","zh":"他喜歡學習，但討厭被測試。"},{"en":"Enjoy the journey — not just the destination.","zh":"享受旅程——不只是目的地。"},{"en":"She found something to enjoy in every situation.","zh":"她在每個情況中都找到了可以享受的東西。"}]},{"word":"prepare","pos":"verb","chinese":"準備；預備","level":"A2","sentences":[{"en":"She prepared thoroughly and it showed in the results.","zh":"她準備充分，結果中有所體現。"},{"en":"I need to prepare for this meeting — give me ten minutes.","zh":"我需要為這個會議做準備——給我十分鐘。"},{"en":"He prepares for the worst while hoping for the best.","zh":"他做最壞的打算，同時希望最好的結果。"},{"en":"Prepare for change — it is the only constant.","zh":"為改變做準備——它是唯一不變的事物。"},{"en":"She prepared a meal for twenty people without breaking a sweat.","zh":"她為二十個人準備了一頓飯，毫不費力。"},{"en":"Being prepared builds confidence.","zh":"有準備會建立自信。"},{"en":"He prepared his speech for weeks but still seemed nervous.","zh":"他為演講準備了幾週，但仍然看起來很緊張。"},{"en":"I am not prepared for how emotional this is going to be.","zh":"我沒有為這會有多感人做好準備。"},{"en":"She prepared the room with flowers and candles — perfect.","zh":"她用花和蠟燭準備好了房間——完美。"},{"en":"Proper preparation prevents poor performance.","zh":"充分的準備防止糟糕的表現。"}]},{"word":"realise","pos":"verb","chinese":"意識到；認識到","level":"A2","sentences":[{"en":"I only realised how tired I was when I sat down.","zh":"直到我坐下來，我才意識到我有多累。"},{"en":"She realised late but she still got there.","zh":"她意識到得晚，但她還是到達了。"},{"en":"He realised he was wrong and apologised immediately.","zh":"他意識到自己錯了，立刻道歉了。"},{"en":"I did not realise how much I had grown until I looked back.","zh":"直到回顧，我才意識到我成長了多少。"},{"en":"She realised that the problem was not outside — it was inside.","zh":"她意識到問題不在外面——而在裡面。"},{"en":"Realising your worth is one of the best things you can do.","zh":"意識到你的價值是你能做的最好的事情之一。"},{"en":"He realised his dream took a completely different shape than planned.","zh":"他意識到他的夢想採取了一種與計畫完全不同的形態。"},{"en":"I just realised we have been talking for three hours.","zh":"我剛意識到我們已經聊了三個小時了。"},{"en":"She did not realise how far she had come.","zh":"她沒有意識到她已經走了多遠。"},{"en":"Realising you need help is a sign of strength.","zh":"意識到你需要幫助是一種力量的表現。"}]},{"word":"worry","pos":"verb/noun","chinese":"擔心；憂慮","level":"A2","sentences":[{"en":"I worry too much about things I cannot control.","zh":"我對我無法控制的事情擔心得太多了。"},{"en":"She worries about everyone except herself.","zh":"她為所有人擔心，唯獨不擔心自己。"},{"en":"Do not worry — I have done this a hundred times.","zh":"不要擔心——我已經做了一百次了。"},{"en":"He has a way of making you worry less.","zh":"他有一種讓你少擔心的方式。"},{"en":"I know I should not worry but I cannot help it.","zh":"我知道我不應該擔心，但我忍不住。"},{"en":"She stopped worrying when she started planning.","zh":"她開始計畫後就停止了擔心。"},{"en":"Worry is just imagination pointed in the wrong direction.","zh":"擔心只是想象力指向了錯誤的方向。"},{"en":"His biggest worry is never having enough time.","zh":"他最大的擔憂是永遠沒有足夠的時間。"},{"en":"Do not worry about tomorrow — today needs your attention.","zh":"不要擔心明天——今天需要你的注意力。"},{"en":"She carried her worries quietly but they were always there.","zh":"她默默地承受著擔憂，但它們一直都在。"}]},{"word":"hope","pos":"verb/noun","chinese":"希望；期望","level":"A2","sentences":[{"en":"I hope you know how much you matter.","zh":"我希望你知道你有多重要。"},{"en":"She holds onto hope even when things look dark.","zh":"即使情況看起來很黑暗，她也抱有希望。"},{"en":"He hoped for the best and planned for the worst.","zh":"他希望最好的結果，同時為最壞的情況做計畫。"},{"en":"I hope this works — we have given it everything.","zh":"我希望這能奏效——我們已經全力以赴了。"},{"en":"She lost hope for a while but found it again.","zh":"她一度失去了希望，但又找到了它。"},{"en":"Hope is not a strategy — but it helps.","zh":"希望不是一種策略——但它有幫助。"},{"en":"He never lost hope even when everyone else did.","zh":"即使其他人都放棄了，他也從未失去希望。"},{"en":"I hope our paths cross again someday.","zh":"我希望有一天我們的路會再次交叉。"},{"en":"She gave others hope just by showing up.","zh":"她只是出現就給了別人希望。"},{"en":"Where there is life, there is always hope.","zh":"有生命的地方，總有希望。"}]},{"word":"miss","pos":"verb","chinese":"想念；錯過","level":"A2","sentences":[{"en":"I miss her every time I hear that song.","zh":"每次聽到那首歌，我都想念她。"},{"en":"She missed the bus but found a better route.","zh":"她錯過了公車，但找到了更好的路線。"},{"en":"Do not miss this opportunity — it will not come again.","zh":"不要錯過這個機會——它不會再來了。"},{"en":"He misses home in a quiet, persistent way.","zh":"他以一種安靜、持續的方式思念家鄉。"},{"en":"I missed you so much — it is good to have you back.","zh":"我非常想念你——很高興你回來了。"},{"en":"She missed the point but arrived at a better one.","zh":"她錯過了重點，但找到了一個更好的觀點。"},{"en":"Missing someone is hard but it means they mattered.","zh":"想念某人很難，但這意味著他們很重要。"},{"en":"He would not miss a single one of his daughter's recitals.","zh":"他不會錯過女兒的任何一場音樂會。"},{"en":"I miss the version of me that had no worries.","zh":"我想念那個沒有煩惱的我。"},{"en":"She missed the detail the first time — caught it on the second read.","zh":"她第一次看時錯過了細節——第二次閱讀時才發現。"}]},{"word":"choose","pos":"verb","chinese":"選擇；挑選","level":"A2","sentences":[{"en":"She chose kindness when she could have chosen revenge.","zh":"她在可以選擇報復時選擇了善良。"},{"en":"You always have a choice — even when it does not feel like it.","zh":"你總是有選擇的——即使感覺不像。"},{"en":"I cannot choose — they are both so good.","zh":"我無法選擇——它們都太好了。"},{"en":"He chose a path less travelled and it made all the difference.","zh":"他選擇了一條少有人走的路，這帶來了巨大的差異。"},{"en":"Choose your hard: hard now or harder later.","zh":"選擇你的艱難：現在艱難，還是之後更艱難。"},{"en":"She chose rest over productivity and it was the right call.","zh":"她選擇了休息而不是生產力，這是正確的決定。"},{"en":"When in doubt, choose the option you will not regret.","zh":"有疑問時，選擇你不會後悔的選項。"},{"en":"He chose his battles carefully.","zh":"他謹慎地選擇了他的戰場。"},{"en":"I choose to see the good in this.","zh":"我選擇從中看到好的一面。"},{"en":"Choosing yourself is not selfish — it is necessary.","zh":"選擇自己並不是自私——而是必要的。"}]},{"word":"change","pos":"verb/noun","chinese":"改變；變化","level":"A2","sentences":[{"en":"She changed her life by changing one small habit.","zh":"她通過改變一個小習慣改變了她的生活。"},{"en":"Change is uncomfortable but growth lives on the other side.","zh":"改變是不舒服的，但成長就在另一面。"},{"en":"He changed so much over the years — for the better.","zh":"多年來他改變了很多——變得更好了。"},{"en":"Can you change your appointment to Thursday?","zh":"你能把預約改到星期四嗎？"},{"en":"She does not fear change — she welcomes it.","zh":"她不害怕改變——她歡迎它。"},{"en":"Change often starts with one conversation.","zh":"改變通常從一次對話開始。"},{"en":"I need a change of scenery — let's get out of here.","zh":"我需要換個環境——我們走吧。"},{"en":"He changed his mind and nobody held it against him.","zh":"他改變了主意，沒有人因此責怪他。"},{"en":"The world changes fast — learn to adapt.","zh":"世界變化很快——學會適應。"},{"en":"She changed the energy of the room just by walking in.","zh":"她只是走進來就改變了整個房間的氛圍。"}]},{"word":"plan","pos":"verb/noun","chinese":"計畫；打算","level":"A2","sentences":[{"en":"She plans everything but stays open to change.","zh":"她計畫一切，但對改變保持開放。"},{"en":"What is the plan for this weekend?","zh":"這個週末的計畫是什麼？"},{"en":"He planned the trip for six months and it was perfect.","zh":"他計畫了六個月的旅行，非常完美。"},{"en":"Plans change — that is part of the adventure.","zh":"計畫會改變——那是冒險的一部分。"},{"en":"I plan to finish this by the end of the week.","zh":"我計畫在週末之前完成這個。"},{"en":"She did not have a plan and somehow that worked.","zh":"她沒有計畫，但不知怎麼就成功了。"},{"en":"Plan for the long term but live in the short term.","zh":"為長遠計畫，但活在當下。"},{"en":"His plan B was better than his plan A.","zh":"他的計畫B比計畫A更好。"},{"en":"I plan less these days and enjoy more.","zh":"我現在計畫少了，享受多了。"},{"en":"A plan is just a good intention without action.","zh":"沒有行動，計畫只是一個美好的意願。"}]},{"word":"share","pos":"verb","chinese":"分享；共享","level":"A2","sentences":[{"en":"She shares everything — food, time, attention.","zh":"她分享一切——食物、時間、注意力。"},{"en":"I want to share something that changed my perspective.","zh":"我想分享一件改變了我視角的事情。"},{"en":"He shared the credit with the whole team.","zh":"他把功勞分給了整個團隊。"},{"en":"Can we share a dessert? I cannot finish a whole one.","zh":"我們可以分享一個甜點嗎？我吃不完一個完整的。"},{"en":"She shared her story and the response was overwhelming.","zh":"她分享了她的故事，反響非常熱烈。"},{"en":"Sharing a meal is one of my love languages.","zh":"分享一頓飯是我的一種愛的語言。"},{"en":"He does not overshare — he chooses what to offer.","zh":"他不會過度分享——他選擇分享什麼。"},{"en":"Sharing vulnerability creates connection.","zh":"分享脆弱可以建立連結。"},{"en":"She shares her knowledge freely and generously.","zh":"她慷慨地分享她的知識。"},{"en":"The best experiences are meant to be shared.","zh":"最好的體驗是要被分享的。"}]},{"word":"support","pos":"verb/noun","chinese":"支持；支援","level":"A2","sentences":[{"en":"She always supports the people she believes in.","zh":"她總是支持她相信的人。"},{"en":"I need your support right now — not your advice.","zh":"我現在需要你的支持——不是你的建議。"},{"en":"He supported her decision even when he disagreed.","zh":"即使他不同意，他也支持了她的決定。"},{"en":"Emotional support is sometimes more valuable than practical help.","zh":"情感支持有時比實際幫助更有價值。"},{"en":"She built a support system before she needed it.","zh":"她在需要之前就建立了支持系統。"},{"en":"Support does not mean agreement — it means showing up.","zh":"支持不意味著同意——而是出現。"},{"en":"I feel so supported in this team.","zh":"我在這個團隊中感到非常被支持。"},{"en":"He supported the cause with both time and money.","zh":"他用時間和金錢支持了這項事業。"},{"en":"Good support can make the impossible feel possible.","zh":"好的支持可以讓不可能的事情感覺可能。"},{"en":"She quietly supported from the background — always there.","zh":"她靜靜地在背後支持——一直都在。"}]},{"word":"experience","pos":"noun/verb","chinese":"經歷；體驗；經驗","level":"A2","sentences":[{"en":"That experience shaped who she is today.","zh":"那段經歷塑造了她今天的樣子。"},{"en":"I have never experienced anything like that before.","zh":"我以前從未經歷過那樣的事情。"},{"en":"He brings ten years of experience to every project.","zh":"他為每個項目帶來十年的經驗。"},{"en":"Every experience — good or bad — teaches you something.","zh":"每一次經歷——好的或壞的——都教你一些東西。"},{"en":"She experienced the city differently because she slowed down.","zh":"她因為放慢腳步，以不同的方式體驗了這座城市。"},{"en":"I want more experiences and fewer things.","zh":"我想要更多體驗，而不是更多物品。"},{"en":"His experience in that field is unmatched.","zh":"他在那個領域的經驗是無與倫比的。"},{"en":"The travel experience changed her entirely.","zh":"旅行體驗完全改變了她。"},{"en":"I am still processing that experience.","zh":"我仍在消化那段經歷。"},{"en":"Experience is the best teacher — and the most expensive.","zh":"經驗是最好的老師——也是最昂貴的。"}]}];
export const VOCAB_LEVELS=["A1","A2","B1","B2"];
